window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[203]={"id":"203","numero":203,"titre":"Dyspnée aiguë et chronique","objectifs":[{"id":"203-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la dyspnée en général et plus particulièrement la dyspnée inspiratoire / expiratoire","contenu":"<p>La <span class=\"kw-def\">dyspnée</span> est la <strong>perception anormale ou désagréable de la respiration</strong>, ressentie lors de situations qui ne génèrent habituellement aucune gêne (repos ou effort modéré). À la différence d'une simple modification du rythme respiratoire, elle comporte une <span class=\"kw-def\">composante sensorielle</span> (oppression thoracique, sensation d'inspiration incomplète) et une <span class=\"kw-def\">composante affective</span> (anxiété, désagrément, frayeur).</p>\n      <p>Physiopathologiquement, c'est une <span class=\"kw-def\">inadéquation entre la demande ventilatoire centrale</span> (commande automatique du tronc cérébral + modulation corticale) <span class=\"kw-def\">et la capacité du système effecteur</span> (muscles respiratoires, thorax, poumon) à y répondre. Ce décalage peut venir de la <span class=\"kw-def\">commande</span>, de l'<span class=\"kw-def\">effecteur</span>, ou des deux à la fois (<span class=\"kw-def\">BPCO</span>, IC chronique, neuromyopathies).</p>\n      <p>La distinction selon le <strong>temps respiratoire</strong> oriente d'emblée vers l'étage anatomique de l'obstacle :</p>\n      <table >\n        <thead><tr><th>Temps</th><th>Origine anatomique</th><th>Bruit / signe associé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Inspiratoire</span> (VAS proximales)</td>\n            <td><span class=\"kw-etio\">Nasale</span>, <span class=\"kw-etio\">oropharyngée</span>, <span class=\"kw-etio\">laryngée</span></td>\n            <td><span class=\"kw-clinique\">Stridor</span> (aigu, vestibulaire/glottique) ; <span class=\"kw-clinique\">cornage</span> (rauque, sous-glottique)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Inspiratoire + expiratoire</span> (2 temps)</td>\n            <td><span class=\"kw-etio\">Trachéale</span></td>\n            <td><span class=\"kw-clinique\">Cornage</span> ou <span class=\"kw-clinique\">wheezing</span> en 2 temps</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Expiratoire</span> (VAI distales)</td>\n            <td><span class=\"kw-etio\">Bronchique</span>, <span class=\"kw-etio\">trachée thoracique basse</span></td>\n            <td><span class=\"kw-clinique\">Wheezing</span> (<span class=\"kw-def\">asthme</span>, <span class=\"kw-def\">BPCO</span>, pseudo-<span class=\"kw-def\">asthme</span> cardiaque)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège classique :</strong> <span class=\"kw-def\">dyspnée ≠ tachypnée</span>. Un patient peut être <span class=\"kw-clinique\">tachypnéique sans être dyspnéique</span> (effort physiologique) et inversement <span class=\"kw-clinique\">dyspnéique sans être tachypnéique</span> (<span class=\"kw-def\">BPCO</span> modérée à FR normale). La <span class=\"kw-clinique\">dyspnée</span> est <strong>subjective</strong> ; la <span class=\"kw-clinique\">tachypnée</span> est un signe <strong>objectif</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 204 — <span class=\"kw-clinique\">Toux</span> · 205 — <span class=\"kw-clinique\">Hémoptysie</span> · 230 — <span class=\"kw-clinique\">Douleur thoracique</span></em></p>","frequence":0},{"id":"203-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître l’examen clinique d’un patient présentant une dyspnée","contenu":"<p>L'examen clinique du dyspnéique est un <strong>raisonnement sémiologique structuré en 7 questions clés</strong> qui orientent d'emblée vers <span class=\"kw-clinique\">les</span> principales étiologies. C'est l'objectif <span class=\"kw-alerte\">le plus tombé en QCM</span> de l'item (5 ⭐) — à maîtriser parfaitement.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Les</span> 7 questions clés à se poser dans l'ordre</h4>\n      <table >\n        <thead><tr><th>#</th><th>Question</th><th>Ce qu'on recherche</th></tr></thead>\n        <tbody>\n          <tr><td>1</td><td><strong>Aiguë ou chronique ?</strong></td><td>Cut-off à <span class=\"kw-chiffre\">8 semaines</span> — bascule la démarche entière</td></tr>\n          <tr><td>2</td><td><strong>Chez qui ?</strong></td><td><span class=\"kw-clinique\">Terrain :</span> âge, <span class=\"kw-etio\">tabagisme</span>, <span class=\"kw-ci\">allergie</span>, ATCD pneumo/cardio/neuro-psy, traitements usuels</td></tr>\n          <tr><td>3</td><td><strong>Facteurs favorisants ?</strong></td><td>Exposition allergénique, <span class=\"kw-ttt\">sevrage</span> <span class=\"kw-etio\">médicamenteux</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">infectieux</span></span>, voyage aérien, <span class=\"kw-ttt\">chirurgie</span> récente, iatrogénie</td></tr>\n          <tr><td>4</td><td><strong>Quand ?</strong></td><td><span class=\"kw-clinique\">Rythmicité :</span> intermittente <span class=\"kw-bio\">vs</span> permanente ; <span class=\"kw-clinique\">horaire :</span> diurne <span class=\"kw-bio\">vs</span> nocturne</td></tr>\n          <tr><td>5</td><td><strong>Comment ?</strong></td><td>Circonstances de survenue : effet <span class=\"kw-clinique\">positionnel</span>, déclenchement à l'<span class=\"kw-clinique\">effort</span></td></tr>\n          <tr><td>6</td><td><strong>Signes respiratoires associés ?</strong></td><td>Bruits (<span class=\"kw-clinique\">cornage</span>, <span class=\"kw-clinique\">sifflements</span>) ; symptômes (<span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">expectorations</span>, <span class=\"kw-clinique\">douleur thoracique</span>) ; signes physiques (<span class=\"kw-clinique\">crépitants</span>, <span class=\"kw-clinique\">sibilants</span>, syndrome pleural)</td></tr>\n          <tr><td>7</td><td><strong>Signes extra-respiratoires ?</strong></td><td>Atteinte pariétale thoracique, atteinte neuromusculaire, atteinte rhumatologique, anomalies cardiaques</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Grand tableau sémiologique discriminant</h4>\n      <table >\n        <thead><tr><th>Axe</th><th>Cluster sémiologique et orientation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Temps</strong></td>\n            <td><strong>Inspiratoire (VAS) :</strong> nasal, oropharyngé, laryngé ;<br><strong>Inspi + expi (trachée) :</strong> trachéal ;<br><strong>Expiratoire (VAI) :</strong> bronchique, trachée basse</td>\n          </tr>\n          <tr>\n            <td><strong>Bruits</strong></td>\n            <td><strong><span class=\"kw-alerte\">Stridor</span> :</strong> aigu, origine <span class=\"kw-etio\">vestibulaire</span>/<span class=\"kw-etio\">glottique</span> ;<br><strong><span class=\"kw-alerte\">Cornage</span> :</strong> rauque, origine <span class=\"kw-etio\">sous-glottique</span> ;<br><strong><span class=\"kw-clinique\">Wheezing</span> expiratoire :</strong> <span class=\"kw-etio\">asthme</span>, <span class=\"kw-etio\">BPCO</span>, <span class=\"kw-etio\">pseudo-asthme cardiaque</span></td>\n          </tr>\n          <tr>\n            <td><strong>Position</strong></td>\n            <td><strong>Antépnée</strong> (penchée en avant) : dysfonction diaphragmatique, <span class=\"kw-etio\">obésité</span> ;<br><strong><span class=\"kw-clinique\">Orthopnée</span></strong> (décubitus pénible) : <span class=\"kw-etio\">insuffisance cardiaque</span>, syndrome cave supérieur, <span class=\"kw-etio\">obésité</span> ;<br><strong>Platypnée</strong> (debout pénible) : shunt anatomique intra-cardiaque (<span class=\"kw-etio\">FOP</span>), intrapulmonaire (<span class=\"kw-clinique\">fistule</span> AV, <span class=\"kw-etio\">syndrome hépato-pulmonaire</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Horaire</strong></td>\n            <td><strong>Nocturne</strong> → 2 diagnostics phares : <span class=\"kw-etio\">OAP</span>, <span class=\"kw-etio\">asthme</span></td>\n          </tr>\n          <tr>\n            <td><strong>Auscultation</strong></td>\n            <td><strong><span class=\"kw-clinique\">Crépitants</span> :</strong> <span class=\"kw-etio\">PID</span>, <span class=\"kw-etio\">ICG</span>, <span class=\"kw-etio\">PAC</span> ;<br><strong><span class=\"kw-clinique\">Sibilants</span> :</strong> <span class=\"kw-etio\">asthme</span>, <span class=\"kw-etio\">BPCO</span>, <span class=\"kw-etio\">ICG</span> (pseudo-<span class=\"kw-def\">asthme</span>) ;<br><strong>Diminution/abolition murmure vésiculaire :</strong> <span class=\"kw-etio\">PAC</span> (diminué), <span class=\"kw-etio\">PNO</span>/<span class=\"kw-etio\">pleurésie</span> (aboli) ;<br><strong>Auscultation normale (<em>sine materia</em>) :</strong> <span class=\"kw-alerte\">EP</span>, <span class=\"kw-alerte\">tamponnade</span>, maladie neuromusculaire, <span class=\"kw-etio\">obésité</span>, scoliose, syndrome d'hyperventilation</td>\n          </tr>\n          <tr>\n            <td><strong>Rythme</strong></td>\n            <td><strong>Kussmaul</strong> (4 temps : inspi/pause/expi/pause) → <span class=\"kw-etio\">acidose métabolique</span> ;<br><strong>Cheyne-Stokes</strong> (polypnées entrecoupées d'apnées) → <span class=\"kw-etio\">IC grave</span>, <span class=\"kw-etio\">SAS central</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Auscultation <em>sine materia</em> = piège majeur.</strong> Devant une <span class=\"kw-clinique\">dyspnée</span> aiguë avec auscultation pulmonaire normale + <span class=\"kw-clinique\">tachycardie</span> sinusale, l'<span class=\"kw-alerte\">embolie pulmonaire</span> est le diagnostic à éliminer en premier — surtout chez le sujet âgé, immobilisé, ou avec ATCD <span class=\"kw-etio\">néoplasique</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 230 — <span class=\"kw-clinique\">Douleur thoracique</span> · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":5},{"id":"203-3","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">dyspnées aiguës</span> (<span class=\"kw-chiffre\">≤ 8</span> sem) se répartissent en <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes catégories</strong> : cardiaques, pulmonaires, autres (anémie, métabolique, anxiété).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes cardiaques</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Signes cliniques évocateurs</th><th>Examen clé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">OAP cardiogénique</span> (ICG)</td>\n            <td><span class=\"kw-clinique\">Orthopnée</span>, <span class=\"kw-clinique\">crépitants bilatéraux</span>, <span class=\"kw-clinique\">expectoration</span> mousseuse rosée, <span class=\"kw-clinique\">galop B3</span></td>\n            <td><span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-bio\">BNP</span> + <span class=\"kw-imagerie\">ETT</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">SCA</span> (équivalent <span class=\"kw-clinique\">dyspnée</span>)</td>\n            <td><span class=\"kw-clinique\">Douleur rétrosternale</span> <span class=\"kw-clinique\">constrictive</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">irradiation</span> MS gauche/mâchoire</td>\n            <td><span class=\"kw-imagerie\">ECG</span> + <span class=\"kw-bio\">troponine</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Tamponnade</span></td>\n            <td><strong>Triade de Beck :</strong> <span class=\"kw-clinique\">turgescence jugulaire</span> + <span class=\"kw-clinique\">hypotension</span> + bruits du cœur assourdis ; pouls paradoxal</td>\n            <td><span class=\"kw-imagerie\">ETT</span> en <span class=\"kw-alerte\">urgence</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes pulmonaires</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Signes cliniques évocateurs</th><th>Examen clé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Embolie pulmonaire</span></td>\n            <td><span class=\"kw-clinique\">Dyspnée</span> brutale + douleur basithoracique pleurale + <span class=\"kw-clinique\">tachycardie</span> ; signes de <span class=\"kw-etio\">TVP</span> éventuels ; auscultation souvent normale</td>\n            <td><span class=\"kw-imagerie\">Angio-TDM</span> ± <span class=\"kw-bio\">D-dimères</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Asthme aigu</span></td>\n            <td><span class=\"kw-clinique\">Sibilants</span> diffus, expiration prolongée, atopie</td>\n            <td><span class=\"kw-bio\">DEP</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Exacerbation de BPCO</span></td>\n            <td><span class=\"kw-etio\">Tabagisme</span> connu, <span class=\"kw-clinique\">sibilants</span>, <span class=\"kw-clinique\">expectoration</span> purulente, <span class=\"kw-clinique\">fièvre</span> possible</td>\n            <td><span class=\"kw-bio\">GDS</span> + <span class=\"kw-imagerie\">RXT</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Pneumonie aiguë communautaire</span></td>\n            <td><span class=\"kw-clinique\">Fièvre</span> + foyer auscultatoire (<span class=\"kw-clinique\">crépitants</span>) + <span class=\"kw-clinique\">expectoration</span> purulente</td>\n            <td><span class=\"kw-imagerie\">RXT</span> (foyer alvéolaire)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Pneumothorax</span></td>\n            <td>Douleur brutale en coup de poignard ; <span class=\"kw-clinique\">abolition du murmure vésiculaire</span> + tympanisme</td>\n            <td><span class=\"kw-imagerie\">RXT</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Pleurésie</span></td>\n            <td><span class=\"kw-clinique\">Matité</span> basale + abolition murmure + abolition vibrations vocales</td>\n            <td><span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-imagerie\">échographie pleurale</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Causes générales / extra-respiratoires</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Signes cliniques évocateurs</th><th>Examen clé</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Anémie aiguë</span></td>\n            <td><span class=\"kw-clinique\">Pâleur</span> + <span class=\"kw-clinique\">tachycardie</span> + saignement éventuel</td>\n            <td><span class=\"kw-bio\">NFS</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Acidose métabolique</span></td>\n            <td><span class=\"kw-clinique\">Dyspnée de Kussmaul</span> 4 temps ; contexte <span class=\"kw-def\">sepsis</span>, acidocétose, <span class=\"kw-def\">IRA</span></td>\n            <td><span class=\"kw-bio\">GDS</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Syndrome d'hyperventilation</span> / anxiété</td>\n            <td>Contexte psy, <span class=\"kw-clinique\">paresthésies extrémités</span>, <span class=\"kw-clinique\">signe de Trousseau</span></td>\n            <td>Diagnostic d'<strong>élimination</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Règle d'or :</strong> toute <span class=\"kw-clinique\">dyspnée aiguë inexpliquée</span> chez l'adulte = <span class=\"kw-alerte\">embolie pulmonaire</span> jusqu'à preuve du contraire — surtout si auscultation normale + <span class=\"kw-clinique\">tachycardie</span> sinusale + <span class=\"kw-def\">terrain</span> à risque thromboembolique.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 209 — <span class=\"kw-def\">BPCO</span> · 154 — Infection bronchopulmonaire communautaire · 360 — <span class=\"kw-imagerie\">Pneumothorax</span> · 206 — Epanchement pleural · 213 — Anémie</em></p>","frequence":3},{"id":"203-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes de gravité devant une dyspnée aiguë","contenu":"<p>Devant toute <span class=\"kw-clinique\">dyspnée aiguë</span>, l'évaluation des <span class=\"kw-alerte\">signes de gravité</span> est <strong>systématique et immédiate</strong> — elle conditionne l'orientation (<span class=\"kw-alerte\">hospitalisation</span>, soins continus, réanimation) et précède l'enquête étiologique.</p>\n\n      <table >\n        <thead><tr><th>Système</th><th><span class=\"kw-alerte\">Signes de gravité</span> à cocher</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Respiratoire</strong></td>\n            <td><span class=\"kw-alerte\">FR &gt; 30/min</span> <strong>ou &lt;<span class=\"kw-chiffre\"> 10/min</span></strong> ; <span class=\"kw-alerte\">SpO<sub>2</sub> &lt; 90 %</span> en <span class=\"kw-def\">air</span> ambiant ; <span class=\"kw-clinique\">cyanose</span> ; <span class=\"kw-clinique\">sueurs</span> ; <span class=\"kw-clinique\">tirage</span> sus-claviculaire/intercostal ; <span class=\"kw-clinique\">balancement thoraco-abdominal</span> ; <span class=\"kw-alerte\">respiration paradoxale</span> (signe d'épuisement diaphragmatique)</td>\n          </tr>\n          <tr>\n            <td><strong>Cardiovasculaire</strong></td>\n            <td><span class=\"kw-alerte\">FC &gt; 120/min</span> ; <span class=\"kw-alerte\">PA syst &lt; 90 mmHg</span> ; <span class=\"kw-clinique\">marbrures</span> ; <span class=\"kw-clinique\">TRC &gt; 3 s</span> ; signes d'<span class=\"kw-etio\">ICD aiguë</span> (<span class=\"kw-clinique\">turgescence jugulaire</span>, RHJ, hépatalgie)</td>\n          </tr>\n          <tr>\n            <td><strong>Neurologique</strong></td>\n            <td><span class=\"kw-alerte\">Agitation</span>, <span class=\"kw-alerte\">confusion</span>, somnolence, <span class=\"kw-alerte\">coma</span> — signent une <span class=\"kw-bio\">hypercapnie</span> ou une hypoxie sévère</td>\n          </tr>\n          <tr>\n            <td><strong>Gazométrique</strong></td>\n            <td><span class=\"kw-bio\">PaO<sub>2</sub> &lt; 60 mmHg</span> ; <span class=\"kw-bio\">PaCO<sub>2</sub> &gt; 45 mmHg</span> avec <span class=\"kw-bio\">pH &lt; 7,35</span> (acidose respiratoire décompensée)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Silence auscultatoire dans l'<span class=\"kw-def\">asthme</span> aigu :</strong> chez un asthmatique en crise, l'absence de <span class=\"kw-clinique\">sibilants</span> n'est <span class=\"kw-alerte\">PAS rassurante</span> — elle signe au contraire le <strong>collapsus bronchique</strong> (débit aérien insuffisant pour générer le moindre <span class=\"kw-clinique\">sibilant</span>). C'est un <span class=\"kw-alerte\">signe de gravité</span> extrême → appeler le réanimateur immédiatement.</div>\n\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-clinique\">Coma</span> et hypercapnie :</strong> un patient <span class=\"kw-def\">BPCO</span> devenu somnolent sous <span class=\"kw-ttt\">oxygénothérapie</span> a probablement une <span class=\"kw-bio\">hypercapnie aggravée par hyperoxie</span> — réduire le débit d'O<sub>2</sub> (cible SpO<sub>2</sub><span class=\"kw-chiffre\"> 88-92 %</span>) et envisager la <span class=\"kw-ttt\">VNI</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"203-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments d’orientation diagnostique face à une dyspnée chronique","contenu":"<p>La <span class=\"kw-def\">dyspnée chronique</span> est définie par une gêne respiratoire persistante <span class=\"kw-chiffre\">≥ 8 semaines</span>. La démarche d'orientation se déroule en <strong>3 temps</strong> : quantification de l'impact, examens de base, orientation étiologique.</p>\n\n      <table >\n        <thead><tr><th>Étape</th><th>Outils</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Quantifier l'impact</strong></td>\n            <td><span class=\"kw-clinique\">Échelle mMRC</span> (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> g</span>rades 0-4) ;<br><span class=\"kw-clinique\">Classification NYHA</span> (1-4) ;<br><span class=\"kw-clinique\">CAT</span> (qualité de vie respiratoire <span class=\"kw-def\">BPCO</span>) ;<br><span class=\"kw-clinique\">HAD/HADS</span> (anxiété-<span class=\"kw-def\">dépression</span> associées) ;<br>Autres : <span class=\"kw-def\">Score</span> DIRECT, EVA, Borg</td>\n          </tr>\n          <tr>\n            <td><strong>2. Examens de base</strong></td>\n            <td><span class=\"kw-bio\">NFS</span> (anémie, <span class=\"kw-def\">syndrome inflammatoire</span>) ;<br><span class=\"kw-imagerie\">ECG</span> (origine cardiaque) ;<br><span class=\"kw-imagerie\">RXT</span> (anomalies pulmonaires)</td>\n          </tr>\n          <tr>\n            <td><strong>3a. Si orientation respiratoire</strong></td>\n            <td><span class=\"kw-bio\">EFR de repos</span> (<span class=\"kw-bio\">spirométrie</span> + pléthysmographie + <span class=\"kw-bio\">DLCO</span>) ;<br><span class=\"kw-bio\">GDS de repos</span> ;<br><span class=\"kw-bio\">TM6</span> ou <span class=\"kw-bio\">lever de chaise 3 min</span> (désaturation à l'effort) ;<br><span class=\"kw-imagerie\">TDM thoracique</span></td>\n          </tr>\n          <tr>\n            <td><strong>3b. Si orientation cardiaque</strong></td>\n            <td>Avis <span class=\"kw-etio\">cardiologique</span> ;<br><span class=\"kw-imagerie\">ETT</span> avec <span class=\"kw-imagerie\">doppler</span> ;<br><span class=\"kw-bio\">BNP / NT-proBNP</span> (seuils chronique : <span class=\"kw-chiffre\">BNP &lt; 35 pg/mL</span> ou <span class=\"kw-chiffre\">NT-proBNP &lt; 125 pg/mL</span> <strong>excluent l'IC chronique</strong>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Échelle mMRC <em>(tombée en annale — à savoir par cœur)</em></h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Grade</span></th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">0</span></td><td><span class=\"kw-clinique\">Dyspnée</span> à l'effort important seulement</td></tr>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td>Pente légère, marche rapide à plat</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td><strong>Arrêt</strong> nécessaire lors de la marche à plat à son pas, ou marche <strong>plus lente</strong> à plat que <span class=\"kw-clinique\">les</span> sujets du même âge</td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td>Arrêt après <span class=\"kw-chiffre\">90 m</span> ou après <strong>quelques minutes</strong> à plat</td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td><span class=\"kw-clinique\">Dyspnée</span> à l'<strong>habillage</strong> ou trop importante pour quitter le domicile</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Classification NYHA</span> (cardiaque)</h4>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">I</span></td><td>Aucune gêne dans la vie courante</td></tr>\n          <tr><td><span class=\"kw-chiffre\">II</span></td><td>Efforts importants habituels (marche rapide, côte, escaliers <span class=\"kw-chiffre\">≥ 2</span> étages)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">III</span></td><td>Efforts peu intenses de la vie courante (marche plate, escaliers &lt; 2 étages)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">IV</span></td><td><span class=\"kw-clinique\">Dyspnée</span> permanente de <strong>repos</strong> ou aux efforts minimes (se laver, s'habiller)</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique · 209 — <span class=\"kw-def\">BPCO</span> · 210 — Pneumopathie interstitielle diffuse · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 110 — Trouble sommeil</em></p>","frequence":4},{"id":"203-6","rang":"A","rubrique":"Etiologies","titre":"Connaître les signes d’orientation étiologique","contenu":"<p>Objectif transversal (aigu + chronique) — 4 ⭐. La <span class=\"kw-clinique\">sémiologie fine</span> guide vers l'étiologie : <strong>temps respiratoire</strong> + <strong>bruits</strong> + <strong>position</strong> + <strong>horaire</strong> + <strong>auscultation</strong>.</p>\n\n      <table >\n        <thead><tr><th>Signe d'orientation</th><th>Étiologies évoquées</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Orthopnée</span></td><td><span class=\"kw-etio\">ICG</span> ; syndrome cave supérieur ; dysfonction diaphragmatique ; <span class=\"kw-etio\">obésité</span> morbide</td></tr>\n          <tr><td><span class=\"kw-clinique\">Platypnée</span> (debout pénible)</td><td>Shunt anatomique : <span class=\"kw-etio\">FOP</span>, <span class=\"kw-clinique\">fistule</span> AV pulmonaire, <span class=\"kw-etio\">syndrome hépato-pulmonaire</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Antépnée</span> (penchée en avant)</td><td>Dysfonction <span class=\"kw-etio\">diaphragmatique</span> ; <span class=\"kw-etio\">obésité</span> morbide</td></tr>\n          <tr><td><span class=\"kw-clinique\">Dyspnée nocturne</span></td><td><span class=\"kw-etio\">OAP</span> ; <span class=\"kw-etio\">asthme</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Stridor inspiratoire</span> (aigu)</td><td>Obstacle <strong>laryngé sus- ou glottique</strong> (<span class=\"kw-alerte\">urgence</span> : <span class=\"kw-alerte\">épiglottite</span>, <span class=\"kw-clinique\">œdème</span>, corps étranger)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Cornage inspiratoire</span> (rauque)</td><td>Obstacle <strong>sous-glottique</strong> (<span class=\"kw-etio\">laryngite sous-glottique</span> de l'enfant)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Wheezing expiratoire</span></td><td><span class=\"kw-etio\">Asthme</span> ; <span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">pseudo-asthme cardiaque</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Crépitants</span></td><td><span class=\"kw-etio\">PID</span> ; <span class=\"kw-etio\">ICG</span> ; <span class=\"kw-etio\">PAC</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Sibilants</span></td><td><span class=\"kw-etio\">Asthme</span> ; <span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">ICG</span> (pseudo-<span class=\"kw-def\">asthme</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Abolition murmure vésiculaire</span></td><td><span class=\"kw-alerte\">PNO</span> (+ tympanisme) ; <span class=\"kw-etio\">pleurésie</span> (+ matité)</td></tr>\n          <tr><td><strong>Auscultation normale (<em>sine materia</em>)</strong></td><td><span class=\"kw-alerte\">EP</span> ; <span class=\"kw-alerte\">tamponnade</span> ; maladie neuromusculaire ; <span class=\"kw-etio\">obésité</span> ; scoliose ; <span class=\"kw-etio\">syndrome d'hyperventilation</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Dyspnée de Kussmaul</span> (4 temps)</td><td><span class=\"kw-etio\">Acidose métabolique</span> (acidocétose, <span class=\"kw-def\">IRA</span>, <span class=\"kw-def\">sepsis</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Dyspnée de Cheyne-Stokes</span></td><td><span class=\"kw-etio\">IC grave</span> ; <span class=\"kw-etio\">SAS central</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Auscultation pulmonaire normale = piège majeur.</strong> Chez l'adulte tabagique, immobilisé ou avec ATCD <span class=\"kw-etio\">néoplasique</span>, c'est l'<span class=\"kw-alerte\">embolie pulmonaire</span> jusqu'à preuve du contraire.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 209 — <span class=\"kw-def\">BPCO</span> · 110 — Trouble sommeil</em></p>","frequence":4},{"id":"203-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","contenu":"<p><strong>Objectif HOT</strong> — <span class=\"kw-alerte\">12 ⭐ brutes en QCM EDN</span>, l'objectif le plus tombé de l'item. Le bilan diffère radicalement selon le caractère <strong>aigu (<span class=\"kw-chiffre\">≤ 8</span> sem)</strong> ou <strong>chronique (<span class=\"kw-chiffre\">≥ 8</span> sem)</strong>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dyspnée</span> aiguë — <span class=\"kw-chiffre\">1ère intention</span></h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Trio systématique</strong></td><td><span class=\"kw-bio\">GDS</span> + <span class=\"kw-imagerie\">ECG</span> + <span class=\"kw-imagerie\">RXT</span></td></tr>\n          <tr><td><strong>Biologie</strong></td><td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">glycémie</span></td></tr>\n          <tr>\n            <td><span class=\"kw-bio\">D-dimères</span></td>\n            <td>Si <strong>suspicion d'EP</strong> avec probabilité <strong>faible ou intermédiaire</strong> :<br>→ <span class=\"kw-chiffre\">&lt; 500 pg/mL</span> <strong>exclut l'EP</strong> (haute valeur prédictive négative)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">BNP / NT-proBNP</span></td>\n            <td>Interprétation devant une <span class=\"kw-clinique\">dyspnée</span> <strong>aiguë</strong> :<br>→ IC <span class=\"kw-clinique\">peu probable</span> si <span class=\"kw-chiffre\">BNP &lt; 100 pg/mL</span> ou <span class=\"kw-chiffre\">NT-proBNP &lt; 300 pg/mL</span> ;<br>→ En faveur du diagnostic d'IC si élevée (seuils <strong>ajustés à l'âge</strong>) :<br>&nbsp;&nbsp;• <span class=\"kw-chiffre\">&gt; 450 pg/mL</span> si âge <span class=\"kw-chiffre\">&lt; 55 ans</span> ;<br>&nbsp;&nbsp;• <span class=\"kw-chiffre\">&gt; 900 pg/mL</span> si <span class=\"kw-chiffre\">55-75 ans</span> ;<br>&nbsp;&nbsp;• <span class=\"kw-chiffre\">&gt; 1 800 pg/mL</span> si <span class=\"kw-chiffre\">&gt; 75 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Stratification probabilité clinique d'EP — préalable indispensable aux <span class=\"kw-bio\">D-dimères</span></h4>\n      <p>Le <span class=\"kw-bio\">score de Wells</span> et le <span class=\"kw-bio\">score de Genève simplifié</span> calibrent la probabilité clinique d'EP <strong>avant</strong> de demander un examen paraclinique. Sans ce <span class=\"kw-def\">score</span>, la séquence diagnostique perd sa logique : <span class=\"kw-alerte\">D-dimères inutiles voire trompeurs si probabilité élevée</span>, <span class=\"kw-alerte\">angio-TDM prématuré si probabilité faible</span>.</p>\n\n      <table >\n        <thead><tr><th>Score de <span class=\"kw-chiffre\">Wells</span></th><th>Points</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Signes cliniques de TVP</span> (<span class=\"kw-clinique\">œdème</span> + douleur mollet)</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td>EP <strong>plus probable</strong> qu'un autre diagnostic</td><td><span class=\"kw-chiffre\">3</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Tachycardie &gt; 100/min</span></td><td><span class=\"kw-chiffre\">1,5</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Immobilisation ≥ 3 j</span> ou <span class=\"kw-clinique\">chirurgie dans les 4 sem</span></td><td><span class=\"kw-chiffre\">1,5</span></td></tr>\n          <tr><td>ATCD de <span class=\"kw-etio\">TVP</span> ou <span class=\"kw-etio\">EP</span></td><td><span class=\"kw-chiffre\">1,5</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hémoptysie</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Cancer actif</span> (traité ou <span class=\"kw-chiffre\">≤ 6 mois</span>)</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Interprétation <span class=\"kw-chiffre\">Wells</span> (version 3 niveaux) :</strong> <span class=\"kw-clinique\">faible</span> &lt; 2 · <span class=\"kw-clinique\">intermédiaire</span> 2-6 · <span class=\"kw-alerte\">élevée</span> <span class=\"kw-chiffre\">≥ 7.</span> La version <strong>dichotomique</strong> simplifie en deux groupes : <span class=\"kw-clinique\">EP improbable ≤ 4</span> · <span class=\"kw-alerte\">EP probable &gt; 4</span>.</p>\n\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Score</span> de Genève simplifié</th><th>Points</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">Âge &gt; 65 ans</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td>ATCD de <span class=\"kw-etio\">TVP</span> ou <span class=\"kw-etio\">EP</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Chirurgie</span> ou <span class=\"kw-clinique\">fracture</span> <span class=\"kw-chiffre\">≤ 1 mois</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Cancer actif</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Douleur unilatérale de membre inférieur</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Hémoptysie</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">FC 75-94/min</span></td><td><span class=\"kw-chiffre\">1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">FC ≥ 95/min</span></td><td><span class=\"kw-chiffre\">2</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Œdème unilatéral</span> + <span class=\"kw-clinique\">douleur à la palpation</span> du mollet</td><td><span class=\"kw-chiffre\">1</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Interprétation Genève simplifié :</strong> <span class=\"kw-clinique\">faible</span> 0-1 · <span class=\"kw-clinique\">intermédiaire</span> 2-4 · <span class=\"kw-alerte\">élevée</span> <span class=\"kw-chiffre\">≥ 5.</span></p>\n\n      <div class=\"callout callout-info\"><strong>Séquence opérationnelle EP — à mémoriser pour <span class=\"kw-clinique\">les</span> QRM :</strong><br>\n      → <span class=\"kw-clinique\">Probabilité faible ou intermédiaire</span> : <span class=\"kw-bio\">D-dimères</span> ; si <span class=\"kw-chiffre\">&lt; 500 pg/mL</span> (ou seuil ajusté à l'âge × 10 chez le sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span>) → EP <strong>exclue</strong>. Si élevés → <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">TDM</span></span>.<br>\n      → <span class=\"kw-alerte\">Probabilité élevée</span> : <span class=\"kw-imagerie\">angio-TDM thoracique d'emblée</span>, <strong>pas de <span class=\"kw-bio\">D-dimères</span></strong> (probabilité pré-test trop forte, faux négatifs possibles, perte de temps).</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dyspnée</span> chronique (<span class=\"kw-chiffre\">≥ 8</span> sem) — <span class=\"kw-chiffre\">1ère intention</span></h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / interprétation</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Trio systématique</strong></td><td><span class=\"kw-bio\">NFS</span> + <span class=\"kw-imagerie\">ECG</span> + <span class=\"kw-imagerie\">RXT</span></td></tr>\n          <tr>\n            <td><span class=\"kw-bio\">BNP / NT-proBNP</span></td>\n            <td>± si suspicion de cardiopathie ; seuils <strong>chronique</strong> très différents :<br>→ <span class=\"kw-chiffre\">BNP &lt; 35 pg/mL</span> <strong>OU</strong> <span class=\"kw-chiffre\">NT-proBNP &lt; 125 pg/mL</span> → <strong>excluent l'IC chronique</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège des seuils <span class=\"kw-bio\">BNP</span> :</strong> <span class=\"kw-clinique\">les</span> seuils sont <span class=\"kw-alerte\">complètement différents en aigu vs chronique</span> (100 <span class=\"kw-bio\">vs</span><span class=\"kw-chiffre\"> 35 pg/mL</span>). À l'inverse, le <span class=\"kw-bio\">BNP</span> est influencé par l'âge, l'<span class=\"kw-ci\">IRC</span>, la <span class=\"kw-ci\">FA</span>, l'<span class=\"kw-etio\">obésité</span> (<span class=\"kw-bio\">BNP</span> <strong>abaissé</strong>). Toujours corréler au contexte.</div>\n\n      <div class=\"callout callout-info\"><strong>Mémo <span class=\"kw-bio\">D-dimères</span> — relecture rapide :</strong> ils n'ont d'intérêt que si la probabilité clinique d'EP est <span class=\"kw-clinique\">faible ou intermédiaire</span> (<span class=\"kw-def\">score</span> de <span class=\"kw-chiffre\">Wells</span> ou de Genève simplifié, cf. bloc ci-dessus). En <span class=\"kw-alerte\">probabilité élevée → angio-TDM directement</span>, sans <span class=\"kw-bio\">D-dimères</span>. <strong>Seuil ajusté à l'âge</strong> chez le sujet &gt;<span class=\"kw-chiffre\"> 50 ans</span> : <span class=\"kw-chiffre\">âge × 10 pg/mL</span> (ex :<span class=\"kw-chiffre\"> 70 ans</span> → seuil <span class=\"kw-chiffre\">700 pg/mL</span> au lieu de 500), pour limiter <span class=\"kw-clinique\">les</span> faux positifs liés au vieillissement.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":12},{"id":"203-8","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de seconde intention en fonction du caractère aigu ou chronique","contenu":"<p>Quand le bilan de <span class=\"kw-chiffre\">1ère intention</span> ne suffit pas, des examens de <strong>seconde intention</strong> sont déclenchés selon l'orientation étiologique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dyspnée</span> aiguë — 2nde intention</h4>\n      <table >\n        <thead><tr><th>Orientation</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Suspicion <span class=\"kw-etio\">EP</span></td>\n            <td><span class=\"kw-imagerie\">Échodoppler veineux des MI</span> ; <span class=\"kw-imagerie\">angio-TDM thoracique</span> ; <span class=\"kw-imagerie\">scintigraphie V/P</span></td>\n          </tr>\n          <tr>\n            <td>Suspicion <span class=\"kw-etio\">IC</span></td>\n            <td><span class=\"kw-imagerie\">ETT avec doppler</span></td>\n          </tr>\n          <tr>\n            <td>Approfondissement fonctionnel</td>\n            <td><span class=\"kw-bio\">EFR</span>, <span class=\"kw-imagerie\">cathétérisme cardiaque</span>, <span class=\"kw-bio\">épreuve d'effort métabolique</span> (EFX)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Dyspnée</span> chronique — 2nde intention selon orientation</h4>\n      <table >\n        <thead><tr><th>Orientation</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cardiaque</strong></td>\n            <td>Avis <span class=\"kw-etio\">cardiologique</span> + <span class=\"kw-imagerie\">ETT</span> systématique ; ± <span class=\"kw-bio\">BNP/NT-proBNP</span> de confirmation</td>\n          </tr>\n          <tr>\n            <td><strong>Respiratoire</strong></td>\n            <td>• <span class=\"kw-bio\">EFR de repos :</span> <span class=\"kw-bio\">spirométrie</span> lente + pléthysmographie + <span class=\"kw-bio\">DLCO</span> ;<br>• <span class=\"kw-bio\">GDS de repos :</span> hypoxémie ? hypoventilation alvéolaire chronique ? ;<br>• <span class=\"kw-bio\">EFR d'exercice :</span> <strong>EFXi sur cycloergomètre</strong> (idéal) ou tests simples : <span class=\"kw-bio\">test de marche 6 min</span>, <span class=\"kw-bio\">lever de chaise 3 min</span> (cible : baisse <span class=\"kw-chiffre\">≥ 3 %</span> SpO<sub>2</sub>) ;<br>• <span class=\"kw-imagerie\">TDM thoracique</span> : <strong>non injectée</strong> si <span class=\"kw-etio\">BPCO</span> ou <span class=\"kw-etio\">PID</span> ; <strong>injectée</strong> si cause vasculaire (<span class=\"kw-etio\">EP chronique</span>, <span class=\"kw-etio\">HTP</span>, shunt D-G)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Mémo <span class=\"kw-bio\">EFR</span> :</strong> <span class=\"kw-bio\">spirométrie</span> lente (<span class=\"kw-bio\">VEMS</span>, CVF) + pléthysmographie (CRF, VR, CPT) + <span class=\"kw-bio\">DLCO</span> (<span class=\"kw-imagerie\">diffusion</span> alvéolo-capillaire). C'est le <strong>triptyque incontournable</strong> du bilan pneumologique de la <span class=\"kw-clinique\">dyspnée</span> chronique.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 208 — <span class=\"kw-ci\">Insuffisance respiratoire</span> chronique · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":1},{"id":"203-9","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies plus rares d’une dyspnée aiguë","contenu":"<p>Étiologies <strong>moins fréquentes</strong> mais à savoir évoquer devant une <span class=\"kw-clinique\">dyspnée</span> aiguë atypique ou résistante au traitement de <span class=\"kw-chiffre\">1ère ligne</span> — <span class=\"kw-alerte\">rang B</span>.</p>\n\n      <table >\n        <thead><tr><th>Étiologie</th><th>Mécanisme</th><th>Signe d'appel</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Anaphylaxie</span> / <span class=\"kw-clinique\">œdème</span> de Quincke</td>\n            <td>Réaction <span class=\"kw-etio\">allergique</span> <span class=\"kw-bio\">IgE-médiée</span></td>\n            <td>Contexte allergénique, <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">hypotension</span>, <span class=\"kw-clinique\">sibilants</span>, <span class=\"kw-clinique\">stridor laryngé</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Inhalation de corps étranger</span> (adulte)</td>\n            <td>Obstruction bronchique mécanique</td>\n            <td><span class=\"kw-clinique\">Syndrome de pénétration</span> ; <span class=\"kw-clinique\">dyspnée</span> + <span class=\"kw-alerte\">tirage</span> + cornage (haut) ; <span class=\"kw-clinique\">sibilants</span> <span class=\"kw-clinique\">asymétriques</span> (bas)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Inhalation toxique</span> (CO, fumées d'incendie)</td>\n            <td>Hypoxie tissulaire / <span class=\"kw-clinique\">lésion</span> alvéolaire chimique</td>\n            <td>Contexte (incendie, chauffage défectueux), <span class=\"kw-clinique\">céphalée</span>, <span class=\"kw-clinique\">vertiges</span>, <span class=\"kw-bio\">HbCO élevée</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Pneumothorax suffocant compressif</span></td>\n            <td>Effet « valve » → <span class=\"kw-clinique\">déviation médiastinale</span></td>\n            <td><span class=\"kw-alerte\">Urgence</span> absolue → <span class=\"kw-ttt\">exsufflation à l'aiguille</span> puis <span class=\"kw-ttt\">drainage</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Tamponnade</span></td>\n            <td><span class=\"kw-imagerie\">Épanchement péricardique</span> compressif</td>\n            <td><strong>Triade de Beck :</strong> <span class=\"kw-clinique\">turgescence jugulaire</span> + <span class=\"kw-clinique\">hypotension</span> + bruits assourdis</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Dissection aortique</span> (extension péricardique)</td>\n            <td>Hémopéricarde aigu</td>\n            <td>Douleur <strong>transfixiante migrante</strong> ; <span class=\"kw-clinique\">asymétrie</span> tensionnelle</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Syndrome d'hyperventilation</span> / crise d'angoisse</td>\n            <td><span class=\"kw-clinique\">Polypnée</span> psychogène avec alcalose respiratoire</td>\n            <td><span class=\"kw-clinique\">Paresthésies</span> périorales/extrémités + <span class=\"kw-clinique\">signe de Trousseau</span> ; diagnostic d'<strong>élimination</strong></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Acidose métabolique</span> (acidocétose, <span class=\"kw-def\">IRA</span>, <span class=\"kw-def\">sepsis</span>)</td>\n            <td>Hyperventilation compensatrice</td>\n            <td><span class=\"kw-clinique\">Dyspnée de Kussmaul</span> en 4 temps</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Atteinte neuromusculaire aiguë</span></td>\n            <td><span class=\"kw-etio\">Guillain-Barré</span>, <span class=\"kw-etio\">myasthénie</span> en crise, <span class=\"kw-etio\">botulisme</span></td>\n            <td><span class=\"kw-clinique\">Dyspnée</span> + atteinte neuro associée (déficit ascendant, ophtalmoplégie)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Syndrome d'hyperventilation = diagnostic d'élimination.</strong> Toujours écarter <span class=\"kw-alerte\">EP</span>, <span class=\"kw-alerte\">acidose métabolique</span>, <span class=\"kw-alerte\">hypoxie objective</span> avant de retenir une origine psychogène — sous peine d'erreur grave.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 360 — <span class=\"kw-imagerie\">Pneumothorax</span> · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"203-10","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies cardiaque et pulmonaire d’une dyspnée chronique","contenu":"<p>Bipartition canonique des <span class=\"kw-clinique\">dyspnées chroniques</span> (<span class=\"kw-chiffre\">≥ 8 semaines</span>) : <strong>cardiaques</strong>, <strong>pulmonaires</strong> et générales (anémie, <span class=\"kw-etio\">obésité</span>, déconditionnement).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies cardiaques</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Insuffisance cardiaque</span> (FEVG altérée ou préservée) — cause cardiaque n°1</li>\n        <li><span class=\"kw-etio\">Coronaropathie chronique</span> — <span class=\"kw-clinique\">angor</span> d'effort, équivalent <span class=\"kw-clinique\">dyspnée</span></li>\n        <li><span class=\"kw-etio\">Valvulopathies</span> — <span class=\"kw-clinique\">rétrécissement aortique serré</span>, IM sévère, RM</li>\n        <li><span class=\"kw-etio\">Cardiopathies congénitales</span> de l'adulte (post-réparation, shunts résiduels)</li>\n        <li><span class=\"kw-etio\">Péricardite chronique constrictive</span></li>\n        <li><span class=\"kw-etio\">HTP postcapillaire</span> (cardiaque) ou <span class=\"kw-etio\">précapillaire</span> (HTAP)</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies pulmonaires</h4>\n      <ul>\n        <li><span class=\"kw-etio\">BPCO</span> — <strong>cause n°1 chez le tabagique</strong></li>\n        <li><span class=\"kw-etio\">Asthme</span> — <span class=\"kw-clinique\">dyspnée</span> d'effort + <span class=\"kw-clinique\">sifflement</span>, <span class=\"kw-clinique\">réversibilité aux β2</span></li>\n        <li><span class=\"kw-etio\">Pneumopathies interstitielles diffuses (PID)</span> — fibrose, <span class=\"kw-clinique\">sarcoïdose</span>, <span class=\"kw-ci\">hypersensibilité</span>, pneumoconioses</li>\n        <li><span class=\"kw-etio\">Dilatation des bronches (DDB)</span> — bronchorrhée chronique, surinfections itératives</li>\n        <li><span class=\"kw-etio\">Cancer pulmonaire</span> — <span class=\"kw-def\">terrain</span> tabagique, <span class=\"kw-clinique\">hémoptysie</span>, <span class=\"kw-clinique\">AEG</span></li>\n        <li><span class=\"kw-etio\">SAOS</span> — somnolence diurne, ronflements, pauses respiratoires nocturnes</li>\n        <li><span class=\"kw-etio\">HTAP</span> primitive ou secondaire (post-<span class=\"kw-etio\">embolique</span>, <span class=\"kw-clinique\">sclérodermie</span>)</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies générales</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Anémie chronique</span> — <span class=\"kw-clinique\">dyspnée</span> d'effort + <span class=\"kw-clinique\">pâleur</span></li>\n        <li><span class=\"kw-etio\">Obésité morbide</span> — syndrome <span class=\"kw-etio\">obésité</span>-hypoventilation (SOH)</li>\n        <li><span class=\"kw-etio\">Déconditionnement physique</span> — diagnostic d'<strong>élimination</strong></li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 233 — Valvulopathie · 209 — <span class=\"kw-def\">BPCO</span> · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 210 — Pneumopathie interstitielle diffuse · 211 — <span class=\"kw-clinique\">Sarcoïdose</span> · 110 — Trouble sommeil · 213 — Anémie</em></p>","frequence":1},{"id":"203-11","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","contenu":"<p>Recoupe partiellement obj-3 et obj-14 (<span class=\"kw-clinique\">les</span> trois objectifs « <span class=\"kw-alerte\">signes de gravité</span> » de la trame officielle). Ici, l'angle est <strong>thérapeutique</strong> : à chaque signe d'alerte correspond un <strong>geste immédiat</strong>. Quatre niveaux d'action s'étagent : <span class=\"kw-ttt\">oxygénothérapie</span> → <span class=\"kw-ttt\">VNI</span> → <span class=\"kw-ttt\">IOT/ventilation</span> → <span class=\"kw-ttt\">geste étiologique</span> (<span class=\"kw-ttt\">drainage</span>, exsufflation, <span class=\"kw-ttt\">adrénaline</span>).</p>\n\n      <table >\n        <thead><tr><th>Signe d'alerte</th><th>Geste immédiat</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">SpO<sub>2</sub> &lt; 90 %</span> sous AA</td>\n            <td><span class=\"kw-ttt\">Oxygénothérapie</span> au masque, titrer pour <span class=\"kw-chiffre\">SpO<sub>2</sub> ≥ 92 %</span> ; <span class=\"kw-alerte\">cible 88-92 %</span> si <span class=\"kw-ci\">BPCO connue</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Détresse</span> respiratoire (<span class=\"kw-alerte\">FR &gt; 30</span>, <span class=\"kw-alerte\">tirage</span>, balancement) + <span class=\"kw-bio\">acidose respiratoire compensée</span></td>\n            <td><span class=\"kw-ttt\">VNI</span> (<span class=\"kw-etio\">BPCO décompensée</span>, <span class=\"kw-etio\">OAP</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Coma</span>, échec <span class=\"kw-ttt\">VNI</span>, acidose sévère</td>\n            <td><span class=\"kw-ttt\">IOT + ventilation mécanique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">PNO compressif</span> (déviation trachée, abolition murmure, tympanisme)</td>\n            <td><span class=\"kw-ttt\">Exsufflation à l'aiguille</span> en <span class=\"kw-alerte\">urgence</span>, puis <span class=\"kw-ttt\">drainage</span> thoracique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Tamponnade</span></td>\n            <td><span class=\"kw-ttt\">Drainage péricardique</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-ttt\">ponction</span> sous écho)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Anaphylaxie</span> avec <span class=\"kw-alerte\">stridor</span></td>\n            <td><span class=\"kw-ttt\">Adrénaline IM 0,5 mg</span> + <span class=\"kw-ttt\">corticoïdes</span> + <span class=\"kw-ttt\">antihistaminiques</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Choc cardiogénique</span></td>\n            <td><span class=\"kw-imagerie\">ETT</span> urgente + remplissage prudent + <span class=\"kw-ttt\">amines vasoactives</span> si besoin</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Asthme aigu grave</span></td>\n            <td><span class=\"kw-ttt\">β2 nébulisés</span> + <span class=\"kw-ttt\">corticoïdes IV</span> + <span class=\"kw-ttt\">sulfate de magnésium</span> ± <span class=\"kw-ttt\">adrénaline</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Cible SpO<sub>2</sub><span class=\"kw-chiffre\"> 88-92 %</span> chez le <span class=\"kw-def\">BPCO</span> :</strong> l'<span class=\"kw-alerte\">hyperoxie aggrave l'hypercapnie</span> par <span class=\"kw-def\">dépression</span> de la commande respiratoire et levée de la vasoconstriction hypoxique. Ne <span class=\"kw-ci\">jamais</span> titrer un <span class=\"kw-def\">BPCO</span> connu à<span class=\"kw-chiffre\"> 100 %</span> de SpO<sub>2</sub>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 332 — Etat de <span class=\"kw-alerte\">choc</span> · 209 — <span class=\"kw-def\">BPCO</span> · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":2},{"id":"203-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications des examens radiologiques devant une dyspnée aiguë et chronique","contenu":"<p>Rang B — récapitulatif des <strong>indications de chaque examen radiologique</strong> selon le contexte (aigu <span class=\"kw-bio\">vs</span> chronique, orientation clinique).</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">RXT F+P</span></td>\n            <td><strong>Systématique</strong> en <span class=\"kw-chiffre\">1ère intention</span> dans <strong>toute</strong> <span class=\"kw-clinique\">dyspnée</span> (aiguë ou chronique)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Angio-TDM thoracique</span></td>\n            <td>Suspicion d'<span class=\"kw-etio\">EP</span> (à coupler aux <span class=\"kw-bio\">D-dimères</span> + <span class=\"kw-def\">score</span> de <span class=\"kw-chiffre\">Wells</span>/Genève) ;<br>Suspicion de <span class=\"kw-def\">pneumonie</span> compliquée, <span class=\"kw-clinique\">abcès</span> ;<br><span class=\"kw-etio\">Dissection aortique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TDM thoracique non injectée</span></td>\n            <td><span class=\"kw-etio\">BPCO</span> ; <span class=\"kw-etio\">PID</span> (en <strong>HRCT</strong> haute résolution) ; suspicion de <span class=\"kw-etio\">cancer pulmonaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie pleurale</span> au lit (POCUS)</td>\n            <td><span class=\"kw-etio\">Épanchement pleural</span> ; <span class=\"kw-clinique\">lignes B</span> (<span class=\"kw-clinique\">œdème</span> pulmonaire) ; <strong>absence de glissement pleural</strong> (<span class=\"kw-alerte\">PNO</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie cardiaque (ETT)</span></td>\n            <td>Suspicion <span class=\"kw-etio\">IC</span> ; <span class=\"kw-etio\">valvulopathie</span> ; <span class=\"kw-alerte\">tamponnade</span> ; <span class=\"kw-etio\">HTP</span> ; cardiopathie hypertrophique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Scintigraphie V/P</span></td>\n            <td><span class=\"kw-etio\">EP</span> en cas de <span class=\"kw-ci\">CI à l'angio-TDM</span> (<span class=\"kw-def\">IRC</span> sévère, <span class=\"kw-ci\">allergie</span> à l'iode, <span class=\"kw-ci\">grossesse</span>)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">IRM cardiaque</span></td>\n            <td>Doute persistant sur cardiopathie : <span class=\"kw-etio\">myocardite</span>, <span class=\"kw-ttt\">infiltration</span>, cardiopathie <span class=\"kw-etio\">congénitale</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>POCUS au lit du patient :</strong> l'<span class=\"kw-imagerie\">échographie pulmonaire et cardiaque</span> au lit devient un outil de <span class=\"kw-chiffre\">1ère ligne</span> aux urgences. Apprendre à distinguer : <span class=\"kw-clinique\">ligne A</span> (normal, fines lignes horizontales), <span class=\"kw-clinique\">lignes B</span> (<span class=\"kw-clinique\">œdème</span> pulmonaire, fusées verticales), <span class=\"kw-clinique\">absence de glissement pleural</span> (PNO).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span></em></p>","frequence":0},{"id":"203-13","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la dyspnée","contenu":"<p>Version condensée de la définition (doublon partiel de la trame officielle — cf. <strong>obj-0</strong> pour le détail temps inspiratoire/expiratoire/2 temps et <span class=\"kw-clinique\">les</span> origines anatomiques).</p>\n      <p>La <span class=\"kw-def\">dyspnée</span> est une <strong>sensation subjective d'inconfort respiratoire</strong> ressentie par le patient. Elle résulte d'une <span class=\"kw-def\">inadéquation entre la commande ventilatoire centrale</span> (tronc cérébral + cortex) <span class=\"kw-def\">et la capacité de réponse du système respiratoire effecteur</span> (muscles + thorax + poumon).</p>\n      <p>Elle comporte toujours deux composantes intriquées :</p>\n      <ul>\n        <li>une <span class=\"kw-def\">composante sensorielle</span>, transmise par des afférences périphériques (mécano- et chémo-récepteurs) jusqu'au cortex — perçue comme oppression thoracique ou inspiration incomplète ;</li>\n        <li>une <span class=\"kw-def\">composante affective / émotionnelle</span> — ressentie comme désagrément, anxiété ou frayeur.</li>\n      </ul>\n      <p>Le mécanisme physiopathologique peut concerner :</p>\n      <ul>\n        <li>la <span class=\"kw-etio\">commande centrale</span> (hyperventilation psychogène, anxiété, trouble neurologique) ;</li>\n        <li><span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">effecteurs</span> (muscles, thorax, poumon — <span class=\"kw-def\">BPCO</span>, <span class=\"kw-def\">asthme</span>, PID) ;</li>\n        <li>ou <strong><span class=\"kw-clinique\">les</span> deux à la fois</strong>, comme c'est souvent le cas dans les pathologies chroniques (<span class=\"kw-def\">BPCO</span> sévère, IC, neuromyopathies).</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>Mémo :</strong> ventilation normale = « <em>félicité respiratoire</em> » — acte mécanique confortable, automatique, silencieux. La <span class=\"kw-def\">dyspnée</span> rompt cette félicité par perception consciente du désaccord demande/capacité.</div>","frequence":0},{"id":"203-14","rang":"A","rubrique":"Diagnostic positif","titre":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","contenu":"<p>Devant une <span class=\"kw-clinique\">dyspnée aiguë</span> (<span class=\"kw-chiffre\">≤ 8</span> sem), 3 axes orientent en quelques minutes vers l'étiologie probable : <strong><span class=\"kw-def\">terrain</span></strong> + <strong>cluster clinique</strong> + <strong>biomarqueurs / <span class=\"kw-imagerie\">RXT</span></strong>.</p>\n\n      <table >\n        <thead><tr><th>Profil clinique</th><th>Cluster sémiologique</th><th>Étiologie probable</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Orthopnée nocturne</span></td>\n            <td><span class=\"kw-clinique\">Crépitants bilatéraux</span> + <span class=\"kw-clinique\">galop B3</span> + <span class=\"kw-clinique\">expectoration</span> mousseuse rosée</td>\n            <td><span class=\"kw-etio\">OAP cardiogénique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Dyspnée brutale</span></td>\n            <td><span class=\"kw-clinique\">Tachycardie</span> + douleur basithoracique pleurale + auscultation <strong>normale</strong> ; ± signes de <span class=\"kw-etio\">TVP</span></td>\n            <td><span class=\"kw-alerte\">Embolie pulmonaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Sifflement expiratoire</span></td>\n            <td><span class=\"kw-clinique\">Sibilants</span> + atopie + DEP effondré, réversibilité aux β2</td>\n            <td><span class=\"kw-etio\">Asthme aigu</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Tabagique connu</span></td>\n            <td><span class=\"kw-clinique\">Sibilants</span> + <span class=\"kw-clinique\">expectoration</span> purulente + signes d'infection</td>\n            <td><span class=\"kw-etio\">Exacerbation de BPCO</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Fièvre + foyer</span></td>\n            <td><span class=\"kw-clinique\">Crépitants</span> en foyer + <span class=\"kw-clinique\">expectoration</span> purulente + <span class=\"kw-clinique\">frissons</span></td>\n            <td><span class=\"kw-etio\">Pneumonie aiguë communautaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Douleur en coup de poignard</span></td>\n            <td><span class=\"kw-clinique\">Abolition unilatérale du murmure</span> + tympanisme + déviation médiastinale possible</td>\n            <td><span class=\"kw-alerte\">Pneumothorax</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Matité basale</span></td>\n            <td><span class=\"kw-clinique\">Matité</span> + abolition murmure + abolition vibrations vocales</td>\n            <td><span class=\"kw-etio\">Épanchement pleural</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Pâleur + tachycardie</span></td>\n            <td>Saignement actif ou chronique extériorisé/non-extériorisé</td>\n            <td><span class=\"kw-etio\">Anémie aiguë</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Polypnée en 4 temps</span></td>\n            <td><span class=\"kw-bio\">Acidose métabolique</span> contexte <span class=\"kw-def\">sepsis</span> / acidocétose / <span class=\"kw-def\">IRA</span></td>\n            <td><span class=\"kw-clinique\">Dyspnée de Kussmaul</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Paresthésies périorales</span></td>\n            <td>Contexte anxieux + <span class=\"kw-clinique\">signe de Trousseau</span> + diagnostic d'élimination</td>\n            <td><span class=\"kw-etio\">Syndrome d'hyperventilation</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Penser EP en priorité</strong> chez tout patient âgé, immobilisé récemment, ATCD <span class=\"kw-etio\">néoplasique</span> ou contraceptif œstroprogestatif présentant une <span class=\"kw-clinique\">dyspnée</span> aiguë + auscultation pulmonaire normale + <span class=\"kw-clinique\">tachycardie</span> sinusale.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP · 234 — <span class=\"kw-def\">Insuffisance cardiaque</span> · 154 — Infection bronchopulmonaire communautaire · 360 — <span class=\"kw-imagerie\">Pneumothorax</span></em></p>","frequence":2},{"id":"203-15","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité accompagnant la dyspnée aiguë","contenu":"<p>Troisième objectif « <span class=\"kw-alerte\">signes de gravité</span> » de la trame officielle EDN (avec obj-3 et obj-10) — ici l'angle est <strong>systématique de reconnaissance d'une <span class=\"kw-alerte\">URGENCE</span></strong>. Le scoring se fait en 5 axes au lit du patient, en moins d'une minute.</p>\n\n      <table >\n        <thead><tr><th>Axe</th><th><span class=\"kw-alerte\"><span class=\"kw-def\">Critères de</span> gravité</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Respiratoire</strong></td>\n            <td><span class=\"kw-alerte\">FR &gt; 30/min</span> <strong>ou &lt;<span class=\"kw-chiffre\"> 10/min</span></strong> ;<br><span class=\"kw-alerte\">SpO<sub>2</sub> &lt; 90 %</span> en AA ;<br><span class=\"kw-clinique\">Cyanose</span> ;<br><span class=\"kw-clinique\">Tirage</span> (sus-claviculaire, intercostal, sus-sternal) ;<br><span class=\"kw-clinique\">Balancement thoraco-abdominal</span> ;<br><span class=\"kw-alerte\">Respiration paradoxale</span> (épuisement) ;<br><span class=\"kw-alerte\">Silence auscultatoire</span> dans l'<span class=\"kw-def\">asthme</span> (collapsus bronchique)</td>\n          </tr>\n          <tr>\n            <td><strong>Circulatoire</strong></td>\n            <td><span class=\"kw-alerte\">FC &gt; 120</span> ou <strong>&lt;<span class=\"kw-chiffre\"> 50/min</span></strong> ;<br><span class=\"kw-alerte\">PA syst &lt; 90 mmHg</span> ;<br><span class=\"kw-clinique\">Marbrures</span> ;<br><span class=\"kw-clinique\">TRC &gt; 3 s</span> ;<br>Signes d'<span class=\"kw-etio\">ICD aiguë</span> : <span class=\"kw-clinique\">turgescence jugulaire</span>, RHJ, hépatalgie</td>\n          </tr>\n          <tr>\n            <td><strong>Neurologique</strong></td>\n            <td><span class=\"kw-alerte\">Agitation</span>, <span class=\"kw-alerte\">confusion</span>, somnolence, <span class=\"kw-alerte\">coma</span> — signent une <span class=\"kw-bio\">hypercapnie</span> ou une hypoxie sévère</td>\n          </tr>\n          <tr>\n            <td><strong>Gazométrique</strong></td>\n            <td><span class=\"kw-bio\">PaO<sub>2</sub> &lt; 60 mmHg</span> ;<br><span class=\"kw-bio\">PaCO<sub>2</sub> &gt; 45 mmHg</span> avec <span class=\"kw-bio\">pH &lt; 7,35</span> (acidose respiratoire décompensée)</td>\n          </tr>\n          <tr>\n            <td><strong>Contexte</strong></td>\n            <td><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">BPCO</span>, <span class=\"kw-etio\">ICC</span> connue, immunodépression, néoplasie évolutive ;<br><span class=\"kw-def\">Comorbidités</span> lourdes ;<br><span class=\"kw-def\">Score</span> <span class=\"kw-clinique\">qSOFA</span> si <span class=\"kw-def\">sepsis</span> suspecté</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Silence auscultatoire = gravité extrême dans l'<span class=\"kw-def\">asthme</span> aigu.</strong> L'absence de <span class=\"kw-clinique\">sibilants</span> chez un asthmatique en crise traduit le <strong>collapsus bronchique</strong> (débit aérien insuffisant) — c'est l'inverse d'un signe rassurant. Appel réanimateur immédiat, <span class=\"kw-ttt\">adrénaline</span> envisageable.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 359 — <span class=\"kw-alerte\">Détresse</span> et <span class=\"kw-ci\">insuffisance respiratoire</span> aiguë · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"203-16","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la stratégie d’exploration en imagerie devant une dyspnée aiguë de l’enfant","contenu":"<p>Objectif <strong>pédiatrique</strong>. Chez l'enfant, l'imagerie d'une <span class=\"kw-clinique\">dyspnée</span> aiguë suit une <span class=\"kw-clinique\">cascade</span> qui dépend du caractère <strong>haut (laryngé)</strong> ou <strong>bas (bronchopulmonaire)</strong> de l'obstacle, et de la <strong>présence ou non de signes de lutte</strong>.</p>\n\n      <table >\n        <thead><tr><th>Contexte clinique</th><th>Stratégie d'imagerie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Dyspnée laryngée en URGENCE</span> avec signes de lutte</td>\n            <td><strong>Pas d'imagerie immédiate.</strong> Priorité = libération des VAS, conditionnement.<br><span class=\"kw-imagerie\">Nasofibroscopie</span> possible dès la naissance pour visualiser le larynx (tube souple petit <span class=\"kw-clinique\">diamètre</span>, ± anesthésie locale/MEOPA).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Dyspnée</span> laryngée <strong>stable</strong></td>\n            <td>1. <span class=\"kw-imagerie\">RX F+P du cou</span> en <span class=\"kw-chiffre\">1ère intention</span> (rayons peu pénétrants, <span class=\"kw-def\">air</span> = contraste) ;<br>2. <span class=\"kw-imagerie\">TDM cervico-thoracique</span> = référence pour étude du larynx (si besoin).</td>\n          </tr>\n          <tr>\n            <td>Suspicion <span class=\"kw-alerte\">inhalation de corps étranger</span></td>\n            <td><span class=\"kw-imagerie\">RXT F+P</span> en <strong>inspiration ET expiration</strong> — signes <strong>indirects</strong> (cf. obj-16). Le cliché expiratoire est <strong>indispensable</strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Bronchiolite</span>, <span class=\"kw-etio\">asthme du nourrisson</span>, <span class=\"kw-etio\">PAC</span></td>\n            <td><span class=\"kw-imagerie\">RXT</span> standard de face.</td>\n          </tr>\n          <tr>\n            <td>Suspicion <span class=\"kw-etio\">EP de l'enfant</span> (rare)</td>\n            <td><span class=\"kw-imagerie\">Écho cardiaque</span> en premier ; <span class=\"kw-imagerie\">angio-TDM</span> en dernier recours.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>RÈGLE DE SURVIE :</strong> en cas de suspicion d'inhalation de corps étranger <strong>avec <span class=\"kw-clinique\">dyspnée</span> laryngée</strong> chez l'enfant, ne <span class=\"kw-alerte\">PAS allonger l'enfant</span> et ne <span class=\"kw-alerte\">PAS faire d'imagerie immédiate</span> — extraire le corps étranger en <span class=\"kw-alerte\">urgence</span> sous AG (risque d'arrêt respiratoire en décubitus).</div>\n\n      <div class=\"callout callout-warn\"><strong>Particularités anatomiques du larynx de l'enfant :</strong> plus haut et proche du nasopharynx (respiration nasale exclusive jusqu'à <span class=\"kw-chiffre\">6 mois</span>) ; proportionnellement plus petit ; <span class=\"kw-clinique\">anneau cricoïdien inextensible</span> = zone la plus étroite → toute inflammation gonfle vite le calibre.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent · 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":0},{"id":"203-17","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les signes indirects sur une radiographie d’un corps étranger bronchique","contenu":"<p>La majorité des <span class=\"kw-clinique\">corps étrangers bronchiques</span> sont <strong>radio-transparents</strong> (organiques : cacahuète, légume, fragment de jouet). Le diagnostic radiologique repose donc sur <span class=\"kw-clinique\">les</span> <strong>signes INDIRECTS</strong>, et le <span class=\"kw-imagerie\">cliché expiratoire</span> est l'examen-clé.</p>\n\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Signe radiologique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Effet « soupape » valvulaire</strong> — le CE laisse passer l'<span class=\"kw-def\">air</span> en inspiration mais bloque l'expiration</td>\n            <td><span class=\"kw-imagerie\">Hyperinflation unilatérale</span> en <strong>EXPIRATION</strong> (cliché expiratoire +++)</td>\n          </tr>\n          <tr>\n            <td><strong>Obstruction complète</strong> — atélectasie d'aval</td>\n            <td><span class=\"kw-imagerie\">Opacité lobaire/segmentaire homogène</span> ; <span class=\"kw-clinique\">attraction médiastinale homolatérale</span> ; surélévation de la coupole diaphragmatique</td>\n          </tr>\n          <tr>\n            <td><strong>Effet partiel persistant</strong></td>\n            <td><span class=\"kw-imagerie\">Asymétrie de transparence pulmonaire</span> entre <span class=\"kw-clinique\">les</span> deux poumons</td>\n          </tr>\n          <tr>\n            <td><strong>Phénomène dynamique respiratoire</strong></td>\n            <td><span class=\"kw-clinique\">Déplacement médiastinal</span> vers le <strong>côté sain</strong> en inspiration / vers le <strong>côté atteint</strong> en expiration</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Air</span>-trapping chronique</strong></td>\n            <td><span class=\"kw-imagerie\">Surdistension unilatérale persistante</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Le cliché EXPIRATOIRE est l'examen clé</strong> chez l'enfant suspect de corps étranger bronchique. Une simple <span class=\"kw-imagerie\">RXT inspiratoire</span> peut être normale et <span class=\"kw-alerte\">faussement rassurer</span> — l'hyperinflation unilatérale (signe de l'<span class=\"kw-def\">air</span>-trapping) n'apparaît qu'en expiration forcée.</div>\n\n      <div class=\"callout callout-warn\"><strong>À compléter.</strong> Le détail des signes radiologiques indirects de CE bronchique n'est que partiellement couvert par <span class=\"kw-clinique\">les</span> fiches sources <code>203-<span class=\"kw-clinique\">dyspnée</span>/</code>. Kevin enrichira plus tard à partir du Collège de Pédiatrie ou de Pneumologie / Pilly / radiopaedia.org.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d'un enfant, d'un adolescent</em></p>","frequence":0},{"id":"203-18","rang":"A","rubrique":"Contenu multimédia","titre":"Radiographie de face dans un contexte de corps étranger","contenu":"<p>Objectif <strong>« Contenu multimédia »</strong> de la trame officielle EDN — lecture iconographique d'une <span class=\"kw-imagerie\">radiographie de face d'enfant</span> dans un contexte de corps étranger bronchique inhalé.</p>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/203/rp-corps-etranger-bronchique.png\" alt=\"Radiographie de thorax de face chez un jeune enfant : inhalation de corps étranger dans la bronche principale droite, avec signes indirects (hyperclarté et augmentation de volume du poumon droit par piégeage, déviation controlatérale du médiastin) et signe direct (objet radio-opaque dans la bronche principale droite)\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">Radiographie de thorax de face</span> chez un jeune enfant — <span class=\"kw-def\">inhalation de corps étranger</span> (bronche principale droite). <strong>Signes indirects :</strong> <span class=\"kw-radio\">hyperclarté et augmentation de volume du poumon droit</span> témoignant du piégeage, <span class=\"kw-radio\">déviation controlatérale du médiastin</span> (flèches). <strong>Signe direct :</strong> <span class=\"kw-radio\">caillou radio-opaque dans la bronche principale droite</span> — le corps étranger n'est visible que s'il est radio-opaque. Source : banque imagerie « Imagerie à connaître » (item 203).</figcaption>\n      </figure>\n\n      <p>Rappel des signes radiologiques indirects à reconnaître (cf. <strong>obj-16</strong>) :</p>\n      <ul>\n        <li><span class=\"kw-imagerie\">Hyperinflation unilatérale</span> en expiration (effet « soupape »)</li>\n        <li><span class=\"kw-clinique\">Asymétrie de transparence pulmonaire</span></li>\n        <li><span class=\"kw-clinique\">Déplacement médiastinal</span> selon le temps respiratoire</li>\n        <li><span class=\"kw-imagerie\">Atélectasie d'aval</span> (opacité homogène) si obstruction complète</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 207 — Opacité intra-thoracique Adulte/Enfant</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> la <span class=\"kw-etio\">dyspnée laryngée</span> est une <span class=\"kw-alerte\">urgence</span> <span class=\"kw-alerte\">diagnostique ET thérapeutique</span> (risque d'<span class=\"kw-alerte\">asphyxie</span>) ; <span class=\"kw-etio\">épiglottite</span> et <span class=\"kw-etio\">spasme laryngé</span> = <span class=\"kw-alerte\">urgence vitale</span><br><strong>Fenêtre :</strong> tout <span class=\"kw-etio\">traumatisme laryngé</span> peut se <span class=\"kw-alerte\">décompenser jusqu'à la 6e heure</span> ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">4 h</span> après une <span class=\"kw-ttt\">nébulisation d'adrénaline</span><br><strong>1er geste :</strong> <span class=\"kw-ttt\">conditionnement</span> — position <span class=\"kw-ttt\">assise / demi-assise</span>, <span class=\"kw-alerte\">ne JAMAIS allonger</span> si <span class=\"kw-etio\">épiglottite</span>, <span class=\"kw-ttt\">oxygénothérapie</span> au masque ou lunettes<br><strong>Piège :</strong> la <span class=\"kw-bio\">SaO2</span> est un mauvais critère dans la <span class=\"kw-clinique\">dyspnée</span> haute (<span class=\"kw-alerte\">décompensation brutale possible malgré une hématose stable</span>) → privilégier la <span class=\"kw-clinique\">clinique</span></p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">laryngite sous-glottique</span> SANS <span class=\"kw-alerte\">détresse</span> respiratoire → <span class=\"kw-ttt\">corticothérapie forte dose PO</span> pendant <span class=\"kw-chiffre\">1-3 jours</span><br><strong>Hospit :</strong> <span class=\"kw-clinique\">dyspnée</span> laryngée <span class=\"kw-alerte\">sévère</span> ; <span class=\"kw-alerte\">mauvaise réponse aux nébulisations</span> de <span class=\"kw-ttt\">corticoïdes</span> / <span class=\"kw-ttt\">adrénaline</span><br><strong>Réa :</strong> <span class=\"kw-etio\">épiglottite</span> → <span class=\"kw-alerte\">hospitalisation</span> en <span class=\"kw-alerte\">réanimation sans délai</span>, recours fréquent à une <span class=\"kw-ttt\">IOT de courte durée</span></p>","redflags":"<ul><li><span class=\"kw-clinique\">Bradypnée inspiratoire</span> + <span class=\"kw-clinique\">stridor / cornage</span> : triade laryngée = signe de lutte et de fatigue</li><li><span class=\"kw-clinique\">Tirage</span> (sus-claviculaire, intercostal, ép<span class=\"kw-chiffre\">iga</span>strique) = signes de lutte d'une obstruction haute</li><li><span class=\"kw-clinique\">Sialorrhée</span> + <span class=\"kw-clinique\">dysphagie intense</span> + enfant <span class=\"kw-clinique\">assis tête penchée en avant</span> → <span class=\"kw-etio\">épiglottite</span></li><li><span class=\"kw-clinique\">Cyanose</span>, <span class=\"kw-alerte\">perte de connaissance</span> → <span class=\"kw-etio\">spasme laryngé</span> / <span class=\"kw-alerte\">asphyxie</span></li><li><span class=\"kw-clinique\">Dyspnée</span> d'apparition <span class=\"kw-alerte\">rapide</span> après <span class=\"kw-etio\">traumatisme laryngé</span> (<span class=\"kw-alerte\">décompensation</span> jusqu'à la <span class=\"kw-chiffre\">6e heure</span>)</li><li><span class=\"kw-clinique\">Crépitants cervicaux</span>, <span class=\"kw-radio\">pneumomédiastin</span> → <span class=\"kw-etio\">fracture laryngée</span> ou brèche pharyngée</li><li><span class=\"kw-alerte\">Décompensation</span> <span class=\"kw-alerte\">brutale possible malgré une hématose stable</span> : <span class=\"kw-bio\">SaO2</span> = mauvais critère, privilégier la <span class=\"kw-clinique\">clinique</span></li></ul>","principes":"<p>Traitement d'<span class=\"kw-alerte\">urgence</span> commun aux dyspnées laryngées aiguës : <span class=\"kw-ttt\">conditionnement</span> + <span class=\"kw-ttt\">corticoïdes / adrénaline</span>, puis mesures selon l'étiologie.</p><p><strong>Conditionnement (tous)</strong></p><ul><li>Position <span class=\"kw-ttt\">assise ou demi-assise</span> (jamais allongé si <span class=\"kw-etio\">épiglottite</span>)</li><li><span class=\"kw-ttt\">Oxygénothérapie</span> au masque ou lunettes nasales si nécessaire</li><li>Chez l'enfant : <span class=\"kw-ttt\">humidification + réchauffement</span> de l'<span class=\"kw-def\">air</span> ; <span class=\"kw-ttt\">monitoring</span> continu</li></ul><p><strong>Enfant — <span class=\"kw-clinique\">dyspnée</span> laryngée aiguë</strong></p><p>Rechercher / traiter un <span class=\"kw-etio\">RGO</span> associé (facteur aggravant fréquent des pathologies laryngées de l'enfant)</p><ul><li><span class=\"kw-ttt\">Corticothérapie</span> : <span class=\"kw-ttt\">dexaméthasone IV</span> puis relais PO par <span class=\"kw-ttt\">prednisone</span> (<span class=\"kw-chiffre\">1 mg/kg/j</span>)</li><li><span class=\"kw-ttt\">Aérosols de Bompard</span> : <span class=\"kw-ttt\">dexaméthasone / bétaméthasone</span> + <span class=\"kw-ttt\">adrénaline</span> + sérum phy.</li><li><span class=\"kw-ttt\">Budésonide inhalé</span> (CSI) : seul si <span class=\"kw-clinique\">dyspnée</span> modérée, ou en relais</li></ul><p><strong>Adulte — traitement symptomatique</strong></p><ul><li><span class=\"kw-ttt\">Corticoïde IV ou IM</span> (<span class=\"kw-chiffre\">1 à 3 mg/kg</span>)</li><li><span class=\"kw-ttt\">Aérosols en continu</span> jusqu'à amélioration : <span class=\"kw-ttt\">adrénaline</span> + <span class=\"kw-ttt\">méthylprednisolone</span> + sérum phy.</li></ul><p><strong>Mesures selon l'étiologie</strong></p><ul><li>Contexte septique / <span class=\"kw-etio\">épiglottite</span> : <span class=\"kw-ttt\">ATB IV</span> après prélèvements (<span class=\"kw-ttt\">Augmentin</span> ou <span class=\"kw-ttt\">C3G + métronidazole</span>)</li><li>Obstacle obstructif : <span class=\"kw-ttt\">désobstruction au laser</span>, <span class=\"kw-ttt\">IOT</span> (préférée) ou <span class=\"kw-ttt\">trachéotomie</span></li></ul>","suivi":"<p><strong>Quantification (<span class=\"kw-clinique\">dyspnée</span> chronique) :</strong> <span class=\"kw-def\">mMRC</span>, <span class=\"kw-def\">NYHA</span>, <span class=\"kw-def\">EVA</span>, <span class=\"kw-def\">Borg</span>, <span class=\"kw-def\">score</span> <span class=\"kw-def\">DIRECT</span> (10 questions)<br><strong>Répercussion / qualité de vie :</strong> questionnaire <span class=\"kw-def\">CAT</span> (santé respiratoire) ; <span class=\"kw-def\">HAD / HADS</span> (anxiété-dépression)<br><strong>Après nébulisation d'<span class=\"kw-ttt\">adrénaline</span> :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">4 h</span> ; hospitaliser si mauvaise réponse<br><strong>Facteur aggravant :</strong> rechercher / traiter un <span class=\"kw-etio\">RGO</span></p>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_203_DYSPNEE_2023.pdf","label":"Collège (CEP) — Item 203 dyspnee 2023"},{"href":"https://radiopaedia.org/articles/larynx","label":"Radiopaedia : Larynx"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Dyspnée laryngée aiguë de l'enfant — Triade : bradypnée + dyspnée inspiratoire + stridor/cornage","detail":"<h4>CAT — <span class=\"kw-clinique\">dyspnée</span> laryngée aiguë de l'enfant — <span class=\"kw-alerte\">Urgence</span> diagnostique et thérapeutique</h4>","branches":[{"to":"q-dra","label":"Évaluer la sévérité","color":"blue"}]},{"id":"q-dra","kind":"decision","label":"Détresse respiratoire / signes de lutte ? — Tirage, cyanose, épuisement","branches":[{"to":"t-ambu","label":"Non (pas de détresse)","color":"green"},{"to":"q-epiglottite","label":"Oui — détresse respiratoire","color":"red"}]},{"id":"t-ambu","kind":"terminal","label":"PEC ambulatoire — corticothérapie PO","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-etio\">Laryngite sous-glottique</span> sans <span class=\"kw-alerte\">détresse</span> → prise en charge <span class=\"kw-ttt\">ambulatoire</span></li><li><span class=\"kw-ttt\">Corticothérapie forte dose per os</span> pendant <span class=\"kw-chiffre\">1-3 jours</span></li></ul><h4>Confirmation</h4><ul><li>Diagnostic <span class=\"kw-clinique\">clinique</span> ; <span class=\"kw-imagerie\">nasofibroscopie</span> seulement si doute</li></ul><h4>Avis ORL</h4><ul><li>Indiqué si <span class=\"kw-clinique\">dyspnée</span> laryngée avant <span class=\"kw-chiffre\">&lt; 6 mois</span> ou laryngites récidivantes</li></ul>"},{"id":"q-epiglottite","kind":"decision","label":"Épiglottite ? — Sialorrhée, sepsis, enfant assis penché en avant, voix couverte","branches":[{"to":"t-rea","label":"Oui (sialorrhée, sepsis, refus de s'allonger)","color":"red"},{"to":"t-hospit","label":"Non (laryngite / laryngomalacie / angiome)","color":"amber"}]},{"id":"t-rea","kind":"terminal","label":"Urgence vitale — réanimation","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Urgence vitale</span> : l'enfant <span class=\"kw-alerte\">ne doit pas être allongé</span> (risque d'obstruction des VAS et d'arrêt respiratoire)</li><li><span class=\"kw-alerte\">Hospitalisation</span> en milieu de <span class=\"kw-alerte\">réanimation sans délai</span></li><li><span class=\"kw-ttt\">ATB IV</span>, recours fréquent à une <span class=\"kw-ttt\">IOT de courte durée</span></li></ul><h4>Reconnaître</h4><ul><li>Installation <span class=\"kw-alerte\">rapide</span>, enfant <span class=\"kw-clinique\">assis dans son lit, tête penchée en avant</span></li><li><span class=\"kw-clinique\">Sepsis</span>, <span class=\"kw-clinique\">dysphagie intense</span> + <span class=\"kw-clinique\">sialorrhée</span>, <span class=\"kw-clinique\">voix étouffée / couverte</span></li><li>Cause : <span class=\"kw-etio\">Haemophilus influenzae b</span> (rare depuis la <span class=\"kw-ttt\">vaccination</span>)</li></ul>"},{"id":"t-hospit","kind":"terminal","label":"Nébulisation + hospitalisation","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Nébulisation de corticoïdes et/ou d'adrénaline</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-ttt\">Corticothérapie forte dose per os</span> pendant <span class=\"kw-chiffre\">1-3 jours</span></li><li>Conditionnement : position <span class=\"kw-ttt\">demi-assise</span>, <span class=\"kw-ttt\">O2</span>, humidification / réchauffement de l'<span class=\"kw-def\">air</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Surveillance</span> <span class=\"kw-chiffre\">4 h</span> après nébulisation d'<span class=\"kw-ttt\">adrénaline</span></li><li><span class=\"kw-alerte\">Hospitalisation si mauvaise réponse</span> aux nébulisations</li></ul><h4>Étiologies (même PEC d'<span class=\"kw-alerte\">urgence</span>)</h4><ul><li>Aggravation aiguë sur <span class=\"kw-etio\">laryngomalacie</span>, <span class=\"kw-etio\">angiome sous-glottique</span>, <span class=\"kw-etio\">laryngite</span></li></ul>"}]},"cards":[{"i":"32b9105f54b5","n":203,"o":"203-1","u":"Définition","t":"Connaître la définition de la dyspnée en général et plus particulièrement la dyspnée inspiratoire / expiratoire","q":"Quelle est la définition générale de la dyspnée ?","a":"<p>La dyspnée est la <strong>perception anormale ou désagréable de la respiration</strong> ressentie lors de situations qui ne génèrent habituellement aucune gêne (repos ou effort modéré). Elle comporte une <strong>composante sensorielle</strong> (oppression thoracique, sensation d'inspiration incomplète) et une <strong>composante affective</strong> (anxiété, désagrément, frayeur).</p>"},{"i":"6179c8051570","n":203,"o":"203-1","u":"Définition","t":"Connaître la définition de la dyspnée en général et plus particulièrement la dyspnée inspiratoire / expiratoire","q":"Quelle est la physiopathologie de la dyspnée ?","a":"<p>Physiopathologiquement, la dyspnée est une <strong>inadéquation entre la demande ventilatoire centrale</strong> (commande automatique du tronc cérébral + modulation corticale) <strong>et la capacité du système effecteur</strong> (muscles respiratoires, thorax, poumon) à y répondre.</p>"},{"i":"8a373dee6425","n":203,"o":"203-1","u":"Définition","t":"Connaître la définition de la dyspnée en général et plus particulièrement la dyspnée inspiratoire / expiratoire","q":"Quel est le piège classique à connaître concernant la dyspnée et à la tachypnée ?","a":"<p>Le piège classique est de confondre dyspnée et tachypnée. La <strong>dyspnée</strong> est une sensation <strong>subjective</strong>, tandis que la <strong>tachypnée</strong> est un signe <strong>objectif</strong> (augmentation de la fréquence respiratoire). Un patient peut être tachypnéique sans être dyspnéeique, et inversement dyspnéeique sans être tachypnéique.</p>"},{"i":"c9023765ec06","n":203,"o":"203-1","u":"Définition","t":"Connaître la définition de la dyspnée en général et plus particulièrement la dyspnée inspiratoire / expiratoire","q":"Comment différencier une dyspnée inspiratoire d'une dyspnée expiratoire en termes d'origine anatomique ?","a":"<ul><li>Une <strong>dyspnée inspiratoire</strong> oriente vers un obstacle des <strong>voies aériennes supérieures proximales</strong> (nasale, oropharyngée, laryngée), souvent associée à un <strong>stridor</strong> ou un <strong>cornage</strong>.</li><li>Une <strong>dyspnée expiratoire</strong> oriente vers un obstacle des <strong>voies aériennes inférieures distales</strong> (bronchique, trachée thoracique basse), souvent associée à un <strong>wheezing</strong> (sifflement).</li></ul>"},{"i":"7b1d3830684a","n":203,"o":"203-10","u":"Etiologies","t":"Connaître les principales étiologies cardiaque et pulmonaire d’une dyspnée chronique","q":"Quelles sont les principales étiologies générales d'une dyspnée chronique ?","a":"<ul><li>L'<strong>anémie chronique</strong>, se manifestant par une dyspnée d'effort associée à une pâleur.</li><li>L'<strong>obésité morbide</strong>, pouvant évoluer vers un syndrome obésité-hypoventilation (SOH).</li><li>Le <strong>déconditionnement physique</strong>, qui est un diagnostic d'élimination.</li></ul>"},{"i":"ac89828d76af","n":203,"o":"203-10","u":"Etiologies","t":"Connaître les principales étiologies cardiaque et pulmonaire d’une dyspnée chronique","q":"Quelles sont les principales étiologies pulmonaires d'une dyspnée chronique ?","a":"<ul><li>La <strong>BPCO</strong> (Bronchopneumopathie Chronique Obstructive), cause numéro 1 chez le tabagique.</li><li>L'<strong>asthme</strong>, caractérisé par une dyspnée d'effort et des sifflements, avec réversibilité aux β2-mimétiques.</li><li>Les <strong>pneumopathies interstitielles diffuses (PID)</strong>, telles que la fibrose, la sarcoïdose, l'hypersensibilité ou les pneumoconioses.</li><li>Les <strong>dilatations des bronches (DDB)</strong>, s'accompagnant d'une bronchorrhée chronique et de surinfections itératives.</li><li>Le <strong>cancer pulmonaire</strong>, à rechercher chez un patient tabagique avec hémoptysie et altération de l'état général (AEG).</li><li>Le <strong>syndrome d'apnées-hypopnées obstructives du sommeil (SAOS)</strong>, avec somnolence diurne, ronflements et pauses respiratoires nocturnes.</li><li>L'<strong>hypertension artérielle pulmonaire (HTAP)</strong> primitive ou secondaire (par exemple, post-embolique, sclérodermie).</li></ul>"},{"i":"d5b1c78c9122","n":203,"o":"203-10","u":"Etiologies","t":"Connaître les principales étiologies cardiaque et pulmonaire d’une dyspnée chronique","q":"Comment définir une dyspnée chronique, et quelles sont les trois grandes catégories étiologiques à considérer ?","a":"<p>Une dyspnée est considérée comme chronique lorsqu'elle évolue depuis <strong>au moins 8 semaines</strong>. Les trois grandes catégories étiologiques sont les causes <strong>cardiaques</strong>, <strong>pulmonaires</strong> et <strong>générales</strong>.</p>"},{"i":"ecc7268c99f2","n":203,"o":"203-10","u":"Etiologies","t":"Connaître les principales étiologies cardiaque et pulmonaire d’une dyspnée chronique","q":"Quelles sont les principales étiologies cardiaques d'une dyspnée chronique ?","a":"<ul><li>L'<strong>insuffisance cardiaque</strong> (à fraction d'éjection ventriculaire gauche altérée ou préservée) est la cause cardiaque numéro 1.</li><li>La <strong>coronaropathie chronique</strong>, pouvant se manifester par un angor d'effort ou un équivalent dyspnée.</li><li>Les <strong>valvulopathies</strong> (par exemple, un rétrécissement aortique serré, une insuffisance mitrale sévère, une insuffisance rénale mitrale).</li><li>Les <strong>cardiopathies congénitales de l'adulte</strong> (post-réparation, shunts résiduels).</li><li>La <strong>péricardite chronique constrictive</strong>.</li><li>L'<strong>hypertension pulmonaire (HTP) post-capillaire</strong> (d'origine cardiaque) ou <strong>pré-capillaire</strong> (HTAP).</li></ul>"},{"i":"247ed6adfaa0","n":203,"o":"203-11","u":"Suivi et/ou pronostic","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quel est le geste d'urgence à réaliser devant un pneumothorax compressif (déviation trachéale, abolition du murmure vésiculaire, tympanisme) ?","a":"<p>Il faut procéder à une <strong>exsufflation à l'aiguille en urgence</strong>, suivie d'un drainage thoracique.</p>"},{"i":"44834dc62762","n":203,"o":"203-11","u":"Suivi et/ou pronostic","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quelle est l'action thérapeutique immédiate face à une détresse respiratoire (FR > 30, tirage, balancement) avec une acidose respiratoire compensée ?","a":"<p>Il faut avoir recours à la <strong>Ventilation Non Invasive (VNI)</strong>, particulièrement indiquée en cas de BPCO décompensée ou d'OAP.</p>"},{"i":"6ad381426cab","n":203,"o":"203-11","u":"Suivi et/ou pronostic","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quelle est la particularité de l'oxygénothérapie chez un patient BPCO connu et pourquoi ?","a":"<p>Chez un patient BPCO connu, la cible de SpO2 est de <strong>88-92%</strong>. L'hyperoxie (SpO2 trop élevée) peut aggraver l'hypercapnie par dépression de la commande respiratoire et levée de la vasoconstriction hypoxique. Il ne faut jamais titrer un BPCO connu à 100% de SpO2.</p>"},{"i":"9397bf68a57c","n":203,"o":"203-11","u":"Suivi et/ou pronostic","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quand faut-il envisager une intubation orotrachéale (IOT) et une ventilation mécanique chez un patient dyspnéique ?","a":"<p>L'IOT et la ventilation mécanique sont indiquées en cas de <strong>coma</strong>, d'<strong>échec de la VNI</strong> ou d'<strong>acidose sévère</strong>.</p>"},{"i":"a651bead5742","n":203,"o":"203-11","u":"Suivi et/ou pronostic","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quelle est la prise en charge immédiate pour une désaturation (SpO2 < 90%) chez un patient présentant une dyspnée aiguë ou chronique, et quelle est la cible de saturation à atteindre ?","a":"<p>La prise en charge immédiate est une <strong>oxygénothérapie au masque</strong>. Il faut titrer le débit pour atteindre une SpO2 ≥ 92%. Pour un patient BPCO connu, la cible est de 88-92%.</p>"},{"i":"ad1086ad8901","n":203,"o":"203-11","u":"Suivi et/ou pronostic","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Quelle est la prise en charge initiale d'une anaphylaxie avec stridor ?","a":"<p>Il faut administrer <strong>0,5 mg d'adrénaline en intramusculaire (IM)</strong>, associée à des corticoïdes et des antihistaminiques.</p>"},{"i":"c7b6689edc1b","n":203,"o":"203-11","u":"Suivi et/ou pronostic","t":"Identifier les signes de gravité imposant des décisions thérapeutiques immédiates","q":"Comment doit-on gérer en urgence une tamponnade cardiaque ?","a":"<p>Le traitement immédiat est un <strong>drainage péricardique en urgence</strong>, idéalement guidé par échographie (ponction sous écho).</p>"},{"i":"1bd816f953c6","n":203,"o":"203-13","u":"Définition","t":"Connaître la définition de la dyspnée","q":"Quel est le mécanisme physiopathologique général de la dyspnée ?","a":"<p>Elle résulte d'une <strong>inadéquation entre la commande ventilatoire centrale</strong> (tronc cérébral + cortex) et la <strong>capacité de réponse du système respiratoire effecteur</strong> (muscles + thorax + poumon).</p>"},{"i":"86366b0f35c5","n":203,"o":"203-13","u":"Définition","t":"Connaître la définition de la dyspnée","q":"Quelle est la définition de la dyspnée en médecine ?","a":"<p>La dyspnée est une <strong>sensation subjective</strong> d'<strong>inconfort respiratoire</strong> ressentie par le patient.</p>"},{"i":"cbc8bef1ca4e","n":203,"o":"203-13","u":"Définition","t":"Connaître la définition de la dyspnée","q":"Quelles sont les deux composantes intriquées de la dyspnée ?","a":"<ul><li>Une <strong>composante sensorielle</strong> : transmise par des afférences périphériques (mécano- et chémorécepteurs) jusqu'au cortex, perçue comme une oppression thoracique ou une inspiration incomplète.</li><li>Une <strong>composante affective/émotionnelle</strong> : ressentie comme un désagrément, de l'anxiété ou de la frayeur.</li></ul>"},{"i":"deee6897f253","n":203,"o":"203-13","u":"Définition","t":"Connaître la définition de la dyspnée","q":"Quelles peuvent être les origines physiopathologiques de la dyspnée ?","a":"<ul><li>Une atteinte de la <strong>commande centrale</strong> (ex : hyperventilation psychogène, anxiété, trouble neurologique).</li><li>Une atteinte des <strong>effecteurs</strong> (muscles, thorax, poumon, ex : BPCO, asthme, PID).</li><li>Une atteinte des <strong>deux à la fois</strong> (fréquent dans les pathologies chroniques comme la BPCO sévère, l'insuffisance cardiaque, les neuromyopathies).</li></ul>"},{"i":"005822e903d7","n":203,"o":"203-14","u":"Diagnostic positif","t":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","q":"Devant une dyspnée aiguë chez un patient tabagique connu, présentant des sibilants, une expectoration purulente et des signes d'infection, quelle étiologie doit être évoquée ?","a":"<p>Ce profil suggère une <strong>exacerbation de bronchopneumopathie chronique obstructive (BPCO)</strong>.</p>"},{"i":"4fe93a09cb95","n":203,"o":"203-14","u":"Diagnostic positif","t":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","q":"En présence d'une dyspnée aiguë brutale associée à une tachycardie, une douleur basithoracique pleurale, une auscultation pulmonaire normale et potentiellement des signes de thrombose veineuse profonde (TVP), à quelle étiologie faut-il penser en priorité ?","a":"<p>Ce tableau clinique oriente vers une <strong>embolie pulmonaire</strong>.</p>"},{"i":"52f082f94cbc","n":203,"o":"203-14","u":"Diagnostic positif","t":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","q":"Devant une dyspnée aiguë avec orthopnée nocturne, crépitants bilatéraux, galop B3 et expectoration mousseuse rosée, quelle est l'étiologie la plus probable ?","a":"<p>Ces signes cliniques sont fortement évocateurs d'un <strong>œdème aigu du poumon (OAP) cardiogénique</strong>.</p>"},{"i":"6f884f551653","n":203,"o":"203-14","u":"Diagnostic positif","t":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","q":"Quels sont les éléments clés permettant d'orienter vers l'étiologie d'une dyspnée aiguë ?","a":"<p>L'orientation étiologique d'une dyspnée aiguë (≤ 8 semaines) repose sur 3 axes principaux :</p><ul><li>Le <strong>terrain du patient</strong>.</li><li>Le <strong>cluster clinique</strong> (signes sémiologiques associés).</li><li>Les <strong>biomarqueurs</strong> et la <strong>radiographie thoracique (RXT)</strong>.</li></ul>"},{"i":"6fc666b76811","n":203,"o":"203-14","u":"Diagnostic positif","t":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","q":"Face à une dyspnée aiguë avec sifflement expiratoire, sibilants, un antécédent d'atopie et un DEP (Débit Expiratoire de Pointe) effondré mais réversible aux bronchodilatateurs bêta-2 mimétiques, quelle est l'étiologie la plus probable ?","a":"<p>Ces éléments sont caractéristiques d'un <strong>asthme aigu</strong>.</p>"},{"i":"7fc73b8750d1","n":203,"o":"203-14","u":"Diagnostic positif","t":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","q":"Quels sont les signes d'alerte suggérant une embolie pulmonaire chez un patient âgé présentant une dyspnée aiguë et une auscultation pulmonaire normale ?","a":"<p>Chez un patient <strong>âgé</strong>, <strong>immobilisé récemment</strong>, avec des <strong>antécédents néoplasiques</strong> ou sous <strong>contraceptif œstroprogestatif</strong>, une <strong>dyspnée aiguë</strong> associée à une <strong>auscultation pulmonaire normale</strong> et une <strong>tachycardie sinusale</strong> doit faire penser en priorité à une <strong>embolie pulmonaire</strong>.</p>"},{"i":"ec646305cee2","n":203,"o":"203-14","u":"Diagnostic positif","t":"Dyspnée aiguë : connaître les éléments d’orientation étiologiques","q":"Quels sont les signes cliniques orientant vers une pneumonie aiguë communautaire en cas de dyspnée aiguë ?","a":"<p>Une <strong>fièvre</strong> associée à un <strong>foyer</strong>, des <strong>crépitants en foyer</strong>, une <strong>expectoration purulente</strong> et des <strong>frissons</strong> orientent vers une pneumonie aiguë communautaire.</p>"},{"i":"11d53790c3dc","n":203,"o":"203-15","u":"Identifier une urgence","t":"Connaître les signes de gravité accompagnant la dyspnée aiguë","q":"Quels sont les cinq axes d'évaluation des signes de gravité d'une dyspnée aiguë au lit du patient ?","a":"<p>Les cinq axes d'évaluation des signes de gravité d'une dyspnée aiguë sont :</p><ul><li><strong>Respiratoire</strong></li><li><strong>Circulatoire</strong></li><li><strong>Neurologique</strong></li><li><strong>Gazométrique</strong></li><li><strong>Contexte</strong></li></ul>"},{"i":"62eb72d5a7fa","n":203,"o":"203-15","u":"Identifier une urgence","t":"Connaître les signes de gravité accompagnant la dyspnée aiguë","q":"Quels sont les critères neurologiques de gravité devant une dyspnée aiguë et que peuvent-ils signifier ?","a":"<p>Les critères neurologiques de gravité devant une dyspnée aiguë sont :</p><ul><li><strong>Agitation</strong></li><li><strong>Confusion</strong></li><li><strong>Somnolence</strong></li><li><strong>Coma</strong></li></ul><p>Ces signes peuvent indiquer une <strong>hypercapnie</strong> ou une <strong>hypoxie sévère</strong>.</p>"},{"i":"6ac2812096a2","n":203,"o":"203-15","u":"Identifier une urgence","t":"Connaître les signes de gravité accompagnant la dyspnée aiguë","q":"Quels sont les critères gazométriques de gravité d'une dyspnée aiguë ?","a":"<p>Les critères gazométriques de gravité d'une dyspnée aiguë sont :</p><ul><li>Pression partielle en oxygène (PaO2) <strong>< 60 mmHg</strong></li><li>Pression partielle en dioxyde de carbone (PaCO2) <strong>> 45 mmHg avec un pH < 7,35</strong> (correspondant à une acidose respiratoire décompensée)</li></ul>"},{"i":"7b5005c575f8","n":203,"o":"203-15","u":"Identifier une urgence","t":"Connaître les signes de gravité accompagnant la dyspnée aiguë","q":"Quels sont les critères respiratoires de gravité devant une dyspnée aiguë ?","a":"<p>Les critères respiratoires de gravité devant une dyspnée aiguë sont :</p><ul><li>Fréquence respiratoire <strong>> 30/min ou < 10/min</strong></li><li>Saturation pulsée en oxygène (SpO2) <strong>< 90 % en air ambiant</strong></li><li><strong>Cyanose</strong></li><li><strong>Tirage</strong> (sus-claviculaire, intercostal, sus-sternal)</li><li><strong>Balancement thoraco-abdominal</strong></li><li><strong>Respiration paradoxale</strong> (signe d'épuisement)</li><li><strong>Silence auscultatoire</strong> dans l'asthme (signe de collapsus bronchique)</li></ul>"},{"i":"aee4ebd44947","n":203,"o":"203-15","u":"Identifier une urgence","t":"Connaître les signes de gravité accompagnant la dyspnée aiguë","q":"Pourquoi un silence auscultatoire est-il un signe de gravité extrême lors d'une crise d'asthme aiguë ?","a":"<p>Un silence auscultatoire est un signe de gravité extrême lors d'une crise d'asthme aiguë car l'<strong>absence de sibilants</strong>, chez un asthmatique en crise, traduit un <strong>collapsus bronchique</strong> avec un débit aérien insuffisant. C'est un signe indiquant une <strong>urgence vitale</strong>, justifiant un appel immédiat au réanimateur et l'éventuelle administration d'<strong>adrénaline</strong>.</p>"},{"i":"bdd841f6e5e7","n":203,"o":"203-15","u":"Identifier une urgence","t":"Connaître les signes de gravité accompagnant la dyspnée aiguë","q":"Quels sont les critères circulatoires de gravité devant une dyspnée aiguë ?","a":"<p>Les critères circulatoires de gravité devant une dyspnée aiguë sont :</p><ul><li>Fréquence cardiaque (FC) <strong>> 120 ou < 50/min</strong></li><li>Pression artérielle systolique (PAS) <strong>< 90 mmHg</strong></li><li><strong>Marbrures</strong></li><li>Temps de recoloration capillaire (TRC) <strong>> 3 secondes</strong></li><li>Signes d'insuffisance cardiaque droite aiguë (ICD aiguë) : <strong>turgescence jugulaire</strong>, <strong>reflux hépatojugulaire (RHJ)</strong>, <strong>hépatalgie</strong>.</li></ul>"},{"i":"09240c94e61b","n":203,"o":"203-16","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration en imagerie devant une dyspnée aiguë de l’enfant","q":"Quelle imagerie doit être réalisée en cas de suspicion d'inhalation de corps étranger chez l'enfant avec une dyspnée ?","a":"<p>Il faut réaliser une <strong>radiographie thoracique de face et de profil en inspiration ET en expiration</strong>. Le cliché expiratoire est <strong>indispensable</strong> car il peut révéler des signes indirects tels qu'un emphysème.</p>"},{"i":"20209e5c7e00","n":203,"o":"203-16","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration en imagerie devant une dyspnée aiguë de l’enfant","q":"Quelle est la stratégie d'imagerie devant une dyspnée laryngée aiguë chez l'enfant avec signes de lutte ?","a":"<p>En présence de signes de lutte intenses, il n'y a <strong>pas d'imagerie immédiate</strong>. La priorité est la <strong>libération des voies aériennes supérieures</strong> et le conditionnement de l'enfant. Une nasofibroscopie est possible pour visualiser le larynx.</p>"},{"i":"550aff6789ea","n":203,"o":"203-16","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration en imagerie devant une dyspnée aiguë de l’enfant","q":"Quelle imagerie préconisez-vous devant une dyspnée laryngée stable de l'enfant ?","a":"<p>En première intention, on réalise une <strong>radiographie du cou de face et de profil</strong>. Si nécessaire, un <strong>scanner cervico-thoracique</strong> est l'examen de référence pour l'étude du larynx.</p>"},{"i":"5904c141575a","n":203,"o":"203-16","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration en imagerie devant une dyspnée aiguë de l’enfant","q":"Quel examen d'imagerie est recommandé en première intention en cas de suspicion d'embolie pulmonaire chez l'enfant ?","a":"<p>Une <strong>échographie cardiaque</strong> est recommandée en première intention. L'angio-TDM est réservée en dernier recours.</p>"},{"i":"71a6d3a49c07","n":203,"o":"203-16","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration en imagerie devant une dyspnée aiguë de l’enfant","q":"Quelle est la règle de survie essentielle en cas de suspicion d'inhalation de corps étranger avec dyspnée laryngée chez l'enfant ?","a":"<p>Il ne faut <strong>PAS allonger l'enfant</strong> et ne <strong>PAS faire d'imagerie immédiate</strong>. La priorité est l'<strong>extraction du corps étranger en urgence sous anesthésie générale</strong>, car il y a un risque d'arrêt respiratoire en décubitus.</p>"},{"i":"c7a65a110735","n":203,"o":"203-16","u":"Examens complémentaires","t":"Connaître la stratégie d’exploration en imagerie devant une dyspnée aiguë de l’enfant","q":"Quelle est la particularité anatomique du larynx de l'enfant qui influence la prise en charge d'une dyspnée aiguë ?","a":"<p>Chez l'enfant, le larynx est plus haut et plus proche du nasopharynx, il est proportionnellement plus petit, et son <strong>anneau cricoïdien est inextensible</strong>. Cette dernière caractéristique rend l'anneau cricoïdien la zone la plus étroite, si bien que toute inflammation peut rapidement réduire le calibre des voies aériennes.</p>"},{"i":"34c253903bdb","n":203,"o":"203-17","u":"Examens complémentaires","t":"Connaître les signes indirects sur une radiographie d’un corps étranger bronchique","q":"Quel est l'examen radiologique clé pour le diagnostic d'un corps étranger bronchique et pourquoi ?","a":"<p>Le <strong>cliché expiratoire</strong> est l'examen clé car il permet de révéler des signes indirects tels que l'hyperinflation unilatérale (phénomène d'air-trapping) qui n'apparaît qu'en expiration forcée. Une radiographie inspiratoire seule peut être normale et faussement rassurante.</p>"},{"i":"3f056ee81ae3","n":203,"o":"203-17","u":"Examens complémentaires","t":"Connaître les signes indirects sur une radiographie d’un corps étranger bronchique","q":"Quel est le principal type de corps étranger bronchique et pourquoi son diagnostic radiologique est-il complexe ?","a":"<p>La majorité des corps étrangers bronchiques sont <strong>radio-transparents</strong> (organiques : cacahuète, légume, fragment de jouet). Leur diagnostic radiologique est donc complexe car ils ne sont pas directement visibles sur les clichés.</p>"},{"i":"7c18d518a87f","n":203,"o":"203-17","u":"Examens complémentaires","t":"Connaître les signes indirects sur une radiographie d’un corps étranger bronchique","q":"Quels sont les signes radiologiques indirects sur une radiographie d'un corps étranger bronchique provoquant une obstruction complète ?","a":"<ul><li><strong>Opacité lobaire/segmentaire homogène</strong> correspondant à une atélectasie d'aval.</li><li><strong>Attraction médiastinale homolatérale</strong> (vers le côté de l'atélectasie).</li><li><strong>Surélévation de la coupole diaphragmatique</strong> du côté atteint.</li></ul>"},{"i":"ecfe764ebe41","n":203,"o":"203-17","u":"Examens complémentaires","t":"Connaître les signes indirects sur une radiographie d’un corps étranger bronchique","q":"Quels sont les signes radiologiques indirects sur une radiographie d'un corps étranger bronchique ayant un effet de soupape valvulaire ?","a":"<ul><li><strong>Hyperinflation unilatérale</strong> en expiration (souvent le signe le plus précoce et le plus évocateur).</li><li><strong>Asymétrie de transparence pulmonaire</strong> entre les deux poumons.</li><li>Déplacement médiastinal : vers le côté sain en inspiration, vers le côté atteint en expiration (phénomène dynamique respiratoire).</li><li>En cas d'air-trapping chronique, on peut observer une <strong>surdistension unilatérale persistante</strong>.</li></ul>"},{"i":"0d049008f3df","n":203,"o":"203-18","u":"Contenu multimédia","t":"Radiographie de face dans un contexte de corps étranger","q":"Comment un corps étranger bronchique peut-il être directement visualisé sur une radiographie thoracique de face chez un enfant ?","a":"<p>Un corps étranger bronchique peut être directement visualisé sur une radiographie thoracique de face <strong>uniquement s'il est radio-opaque</strong>, comme un caillou, apparaissant alors comme une opacité au niveau de la bronche principale concernée.</p>"},{"i":"166341b03dcc","n":203,"o":"203-18","u":"Contenu multimédia","t":"Radiographie de face dans un contexte de corps étranger","q":"Quels sont les signes radiologiques indirects d'un corps étranger bronchique inhalé chez un enfant, en particulier ceux visibles sur une radiographie thoracique de face ?","a":"<p>Les signes radiologiques indirects d'un corps étranger bronchique inhalé sont :</p><ul><li>Une <strong>hyperclarté et augmentation de volume</strong> du poumon, témoignant d'un piégeage aérien.</li><li>Une <strong>déviation controlatérale du médiastin</strong>.</li><li>Une <strong>hyperinflation unilatérale en expiration</strong> (effet « soupape »).</li><li>Une <strong>asymétrie de transparence pulmonaire</strong>.</li><li>Un <strong>déplacement médiastinal selon le temps respiratoire</strong>.</li><li>Une <strong>atélectasie d'aval</strong> (opacité homogène) en cas d'obstruction complète.</li></ul>"},{"i":"d48ec41e6eb7","n":203,"o":"203-18","u":"Contenu multimédia","t":"Radiographie de face dans un contexte de corps étranger","q":"Quel est le mécanisme physiologique de l'hyperclarté et de l'augmentation de volume pulmonaire en aval d'un corps étranger bronchique ?","a":"<p>L'hyperclarté et l'augmentation de volume pulmonaire en aval d'un corps étranger bronchique résultent d'un phénomène de <strong>piégeage aérien</strong>. Le corps étranger agit comme une « <strong>soupape</strong> », permettant à l'air d'entrer dans le poumon à l'inspiration, mais l'empêchant de sortir complètement à l'expiration, conduisant à une hyperinflation.</p>"},{"i":"177ce85d3bc9","n":203,"o":"203-2","u":"Diagnostic positif","t":"Connaître l’examen clinique d’un patient présentant une dyspnée","q":"Quelles sont les significations cliniques des crépitants et des sibilants à l'auscultation pulmonaire chez un patient dyspnéique ?","a":"<p>À l'auscultation pulmonaire :</p><ul><li>Les <strong>crépitants</strong> orientent vers une <strong>pneumopathie interstitielle diffuse (PID)</strong>, une <strong>insuffisance cardiaque gauche (ICG)</strong> ou une <strong>pneumonie aiguë communautaire (PAC)</strong>.</li><li>Les <strong>sibilants</strong> orientent vers l'<strong>asthme</strong>, la <strong>BPCO</strong>, ou un pseudo-asthme dû à une <strong>insuffisance cardiaque gauche (ICG)</strong>.</li></ul>"},{"i":"47f264d14fb8","n":203,"o":"203-2","u":"Diagnostic positif","t":"Connaître l’examen clinique d’un patient présentant une dyspnée","q":"Dans quelles situations l'auscultation pulmonaire normale (sine materia) chez un patient dyspnéique est-elle un piège diagnostique majeur ?","a":"<p>Une auscultation pulmonaire normale (<strong>sine materia</strong>) face à une dyspnée est un piège. Elle peut orienter vers :</p><ul><li>Une <strong>embolie pulmonaire (EP)</strong>, surtout si associée à une <strong>tachycardie sinusale</strong>, chez un sujet âgé, immobilisé ou avec des antécédents néoplasiques. L'EP est le premier diagnostic à éliminer dans ce contexte aigu.</li><li>Une <strong>tamponnade cardiaque</strong>.</li><li>Une <strong>maladie neuromusculaire</strong>.</li><li>Une <strong>obésité</strong> importante ou une <strong>scoliose</strong>.</li><li>Un <strong>syndrome d'hyperventilation</strong>.</li></ul>"},{"i":"78bf9634538e","n":203,"o":"203-2","u":"Diagnostic positif","t":"Connaître l’examen clinique d’un patient présentant une dyspnée","q":"Comment l'axe sémiologique du temps inspiratoire et expiratoire permet-il d'orienter le diagnostic étiologique de la dyspnée ?","a":"<p>L'axe du temps d'apparition permet d'orienter l'étiologie :</p><ul><li>Dyspnée à temps <strong>inspiratoire</strong> (associée à une <strong>VAS</strong> : voies aériennes supérieures) : oriente vers une obstruction nasale, oropharyngée ou laryngée.</li><li>Dyspnée à temps <strong>inspiratoire ET expiratoire</strong> (associée à la <strong>trachée</strong>) : oriente vers une obstruction trachéale.</li><li>Dyspnée à temps <strong>expiratoire</strong> (associée aux <strong>VAI</strong> : voies aériennes inférieures) : oriente vers une pathologie bronchique ou trachéale basse, comme l'<strong>asthme</strong> ou la <strong>BPCO</strong>.</li></ul>"},{"i":"aec856b5fb20","n":203,"o":"203-2","u":"Diagnostic positif","t":"Connaître l’examen clinique d’un patient présentant une dyspnée","q":"Quelles sont les 7 questions clés de l'examen clinique d'un patient dyspnéique pour orienter le diagnostic étiologique ?","a":"<p>Ces questions, à poser dans l'ordre, sont :</p><ul><li>La dyspnée est-elle <strong>aiguë</strong> ou <strong>chronique</strong> (seuil de <strong>8 semaines</strong>) ?</li><li><strong>Chez qui</strong> survient-elle (terrain : âge, tabagisme, antécédents, traitements) ?</li><li>Y a-t-il des <strong>facteurs favorisants</strong> (expositions, sevrage médicamenteux, infection, voyage, chirurgie) ?</li><li><strong>Quand</strong> survient-elle (rythmicité, horaire, par exemple <strong>nocturne</strong>) ?</li><li><strong>Comment</strong> survient-elle (position, effort) ?</li><li>Y a-t-il des <strong>signes respiratoires associés</strong> (bruits type <strong>cornage, sifflements</strong> ; symptômes comme toux, expectorations, douleur thoracique ; signes physiques comme <strong>crépitants, sibilants</strong>, syndrome pleural) ?</li><li>Y a-t-il des <strong>signes extra-respiratoires</strong> (atteinte pariétale, neuromusculaire, rhumatologique, anomalies cardiaques) ?</li></ul>"},{"i":"b94b2ff52841","n":203,"o":"203-2","u":"Diagnostic positif","t":"Connaître l’examen clinique d’un patient présentant une dyspnée","q":"Quels sont les bruits et positions sémiologiques clés à rechercher à l'examen clinique d'un patient dyspnéique et leurs significations ?","a":"<p>Les bruits et positions permettent d'orienter vers certaines pathologies :</p><ul><li><strong>Bruits </strong>:<ul><li><strong>Stridor</strong> : aigu, origine <strong>vestibulaire ou glottique</strong>.</li><li><strong>Cornage</strong> : rauque, origine <strong>sous-glottique</strong>.</li><li><strong>Wheezing expiratoire</strong> : typique de l'<strong>asthme</strong>, la <strong>BPCO</strong> (ou pseudo-asthme cardiaque).</li></ul></li><li><strong>Positions </strong>:<ul><li><strong>Antépnée</strong> (penchée en avant) : suspecter une <strong>dysfonction diaphragmatique</strong> ou une obésité.</li><li><strong>Orthopnée</strong> (décubitus pénible) : évoque une <strong>insuffisance cardiaque</strong>, un syndrome cave supérieur ou une obésité.</li><li><strong>Platypnée</strong> (debout pénible) : suggère un <strong>shunt anatomique</strong> intracardiaque (<strong>FOP</strong>) ou intrapulmonaire.</li></ul></li></ul>"},{"i":"078cfcecc2d5","n":203,"o":"203-3","u":"Etiologies","t":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","q":"Quelle est la règle d'or concernant l'orientation diagnostique d'une dyspnée aiguë inexpliquée chez un adulte ?","a":"<p>Toute dyspnée aiguë inexpliquée chez l'adulte doit être considérée comme une <strong>embolie pulmonaire</strong> jusqu'à preuve du contraire, particulièrement en cas d'<strong>auscultation normale</strong>, de <strong>tachycardie sinusale</strong> et d'un <strong>terrain à risque thromboembolique</strong>.</p>"},{"i":"6f0f09c910b8","n":203,"o":"203-3","u":"Etiologies","t":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","q":"Quels signes orientent vers une embolie pulmonaire en cas de dyspnée aiguë, et l'examen clé pour son diagnostic ?","a":"<p>Devant une dyspnée aiguë, une embolie pulmonaire est évoquée par une <strong>dyspnée brutale</strong>, une <strong>douleur basithoracique pleurale</strong>, une <strong>tachycardie</strong>, et la présence éventuelle de <strong>signes de thrombose veineuse profonde (TVP)</strong>. L'auscultation est souvent <strong>normale</strong>.</p><p>L'examen clé est l'<strong>angio-TDM pulmonaire</strong>, éventuellement précédée des <strong>D-dimères</strong>.</p>"},{"i":"7fdaa2ad2936","n":203,"o":"203-3","u":"Etiologies","t":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","q":"Comment définir une dyspnée aiguë et quelles sont les grandes catégories étiologiques à considérer ?","a":"<p>Une dyspnée aiguë est une gêne respiratoire d'installation rapide, évoluant depuis <strong>moins de 8 semaines</strong>. Ses grandes catégories étiologiques sont :</p><ul><li>Les causes <strong>cardiaques</strong>.</li><li>Les causes <strong>pulmonaires</strong>.</li><li>Les causes <strong>générales/extra-respiratoires</strong> (anémie, métabolique, anxiété).</li></ul>"},{"i":"8adff0cd13d0","n":203,"o":"203-3","u":"Etiologies","t":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","q":"Quels sont les signes cliniques évocateurs d'un œdème aigu du poumon (OAP) cardiogénique, et l'examen clé pour son diagnostic ?","a":"<p>Les signes cliniques évocateurs d'un OAP cardiogénique sont : <strong>orthopnée</strong>, <strong>crépitants bilatéraux</strong>, expectoration <strong>mousseuse rosée</strong> et <strong>galop B3</strong>.</p><p>L'examen clé est la <strong>radiographie thoracique (RXT)</strong>, associée au <strong>BNP</strong> et à l'<strong>échographie transthoracique (ETT)</strong>.</p>"},{"i":"d29dbd5ca78f","n":203,"o":"203-3","u":"Etiologies","t":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","q":"Quels sont les signes cliniques évocateurs des causes générales/extra-respiratoires de dyspnée aiguë (anémie, acidose métabolique, syndrome d'hyperventilation) ?","a":"<ul><li><strong>Anémie aiguë</strong> : <strong>pâleur</strong>, <strong>tachycardie</strong>, et un éventuel <strong>saignement</strong>.</li><li><strong>Acidose métabolique</strong> : <strong>dyspnée de Kussmaul</strong> (4 temps), dans un contexte de <strong>sepsis</strong>, d'<strong>acidocétose</strong> ou d'<strong>insuffisance rénale aiguë (IRA)</strong>.</li><li><strong>Syndrome d'hyperventilation/anxiété</strong> : contexte <strong>psychologique</strong>, <strong>paresthésies des extrémités</strong>, <strong>signe de Trousseau</strong>. C'est un diagnostic d'élimination.</li></ul>"},{"i":"ef805b8641ed","n":203,"o":"203-3","u":"Etiologies","t":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","q":"Quels sont les signes cliniques distinctifs d'un asthme aigu et d'une exacerbation de BPCO en cas de dyspnée aiguë ?","a":"<ul><li>Pour l'<strong>asthme aigu</strong> : <strong>sibilants diffus</strong>, <strong>expiration prolongée</strong>, et un contexte d'<strong>atopie</strong>.</li><li>Pour l'<strong>exacerbation de BPCO</strong> : contexte de <strong>tabagisme connu</strong>, <strong>sibilants</strong>, <strong>expectoration purulente</strong>, et une possible <strong>fièvre</strong>.</li></ul>"},{"i":"f6e2c8f7ca28","n":203,"o":"203-3","u":"Etiologies","t":"Connaître les principales étiologies d’une dyspnée aiguë et leur signes cliniques","q":"Quels signes cliniques et examens clés permettent de différencier une pneumonie aiguë communautaire, un pneumothorax et une pleurésie devant une dyspnée aiguë ?","a":"<ul><li><strong>Pneumonie aiguë communautaire</strong> : <strong>fièvre</strong>, <strong>foyer auscultatoire (crépitants)</strong>, <strong>expectoration purulente</strong>. L'examen clé est la <strong>RXT</strong> montrant un foyer alvéolaire.</li><li><strong>Pneumothorax</strong> : <strong>douleur brutale en coup de poignard</strong>, <strong>abolition du murmure vésiculaire</strong>, <strong>tympanisme</strong> à la percussion. L'examen clé est la <strong>RXT</strong>.</li><li><strong>Pleurésie</strong> : <strong>matité basale</strong>, <strong>abolition du murmure vésiculaire</strong>, <strong>abolition des vibrations vocales</strong>. Les examens clés sont la <strong>RXT</strong> et l'<strong>échographie pleurale</strong>.</li></ul>"},{"i":"5a90a4f517b5","n":203,"o":"203-4","u":"Diagnostic positif","t":"Connaître les signes de gravité devant une dyspnée aiguë","q":"Quelles anomalies gazométriques définissent un état de gravité lors d'une dyspnée aiguë ?","a":"Les anomalies gazométriques graves sont :<ul><li>PaO2 <strong>< 60 mmHg</strong></li><li>PaCO2 <strong>> 45 mmHg</strong> avec un pH <strong>< 7,35</strong> (correspondant à une acidose respiratoire décompensée)</li></ul>"},{"i":"80556c8809bd","n":203,"o":"203-4","u":"Diagnostic positif","t":"Connaître les signes de gravité devant une dyspnée aiguë","q":"Quels sont les signes de gravité respiratoires à rechercher face à une dyspnée aiguë ?","a":"Les signes de gravité respiratoires sont :<ul><li>Fréquence respiratoire <strong>> 30/min</strong> ou <strong>< 10/min</strong></li><li>Saturation en oxygène (SpO2) <strong>< 90 %</strong> en air ambiant</li><li><strong>Cyanose</strong></li><li><strong>Sueurs</strong></li><li><strong>Tirage</strong> sus-claviculaire/intercostal</li><li><strong>Balancement thoraco-abdominal</strong></li><li><strong>Respiration paradoxale</strong> (signe d'épuisement diaphragmatique)</li></ul>"},{"i":"851ae6faf8d1","n":203,"o":"203-4","u":"Diagnostic positif","t":"Connaître les signes de gravité devant une dyspnée aiguë","q":"Comment adapter l'oxygénothérapie chez un patient BPCO présentant une dyspnée aiguë et une somnolence ?","a":"Chez un patient BPCO devenant <strong>somnolent sous oxygénothérapie</strong>, il faut suspecter une <strong>hypercapnie aggravée par l'hyperoxie</strong>. Il convient alors de <strong>réduire le débit d'O2</strong> avec une cible de SpO2 entre <strong>88 et 92 %</strong> et d'envisager une <strong>ventilation non invasive (VNI)</strong>."},{"i":"9cfb02c240ef","n":203,"o":"203-4","u":"Diagnostic positif","t":"Connaître les signes de gravité devant une dyspnée aiguë","q":"Quels signes neurologiques doivent alerter sur la gravité d'une dyspnée aiguë et à quoi peuvent-ils correspondre ?","a":"Les signes neurologiques d'alerte sont l'<strong>agitation</strong>, la <strong>confusion</strong>, la <strong>somnolence</strong> et le <strong>coma</strong>. Ils peuvent signer une <strong>hypercapnie</strong> ou une <strong>hypoxie sévère</strong>."},{"i":"ba1f3dc05e0d","n":203,"o":"203-4","u":"Diagnostic positif","t":"Connaître les signes de gravité devant une dyspnée aiguë","q":"Quels sont les signes de gravité cardiovasculaires à prendre en compte devant une dyspnée aiguë ?","a":"Les signes de gravité cardiovasculaires incluent :<ul><li>Fréquence cardiaque (FC) <strong>> 120/min</strong></li><li>Pression artérielle systolique (PA syst) <strong>< 90 mmHg</strong></li><li><strong>Marbrures</strong></li><li>Temps de recoloration capillaire (TRC) <strong>> 3 secondes</strong></li><li>Signes d'insuffisance cardiaque droite (ICD) aiguë (<strong>turgescence jugulaire</strong>, <strong>reflux hépatojugulaire</strong>, <strong>hépatalgie</strong>)</li></ul>"},{"i":"c24faa41c51d","n":203,"o":"203-4","u":"Diagnostic positif","t":"Connaître les signes de gravité devant une dyspnée aiguë","q":"Pourquoi un \"silence auscultatoire\" chez un asthmatique en crise est-il un signe de gravité extrême ?","a":"Chez un asthmatique en crise, le <strong>silence auscultatoire</strong> n'est <strong>PAS rassurant</strong>. Il signifie que le débit aérien est insuffisant pour générer des sibilants en raison d'un <strong>collapsus bronchique</strong>. C'est un <strong>signe de gravité extrême</strong> qui doit faire envisager l'appel immédiat d'un réanimateur."},{"i":"00285325d874","n":203,"o":"203-5","u":"Diagnostic positif","t":"Connaître les éléments d’orientation diagnostique face à une dyspnée chronique","q":"Quels examens complémentaires sont indiqués en cas de suspicion d'orientation respiratoire pour une dyspnée chronique?","a":"<p>En cas d'orientation respiratoire forte devant une dyspnée chronique, les examens complémentaires à prévoir sont :</p><ul><li>Des <strong>Explorations Fonctionnelles Respiratoires (EFR) de repos</strong> incluant spirométrie, pléthysmographie et mesure de la DLCO.</li><li>Des <strong>Gaz du Sang (GDS) de repos</strong>.</li><li>Un <strong>test de marche de 6 minutes (TM6)</strong> ou un <strong>lever de chaise de 3 minutes</strong> pour évaluer la désaturation à l'effort.</li><li>Un <strong>Scanner thoracique</strong>.</li></ul>"},{"i":"1d3e6a393115","n":203,"o":"203-5","u":"Diagnostic positif","t":"Connaître les éléments d’orientation diagnostique face à une dyspnée chronique","q":"Quels sont les examens de base à réaliser devant une dyspnée chronique pour orienter le diagnostic étiologique?","a":"<p>Devant une dyspnée chronique, les examens de base à réaliser pour l'orientation diagnostique sont :</p><ul><li>Une <strong>Numération Formule Sanguine (NFS)</strong> pour rechercher une anémie ou un syndrome inflammatoire.</li><li>Un <strong>Électrocardiogramme (ECG)</strong> pour rechercher une origine cardiaque.</li><li>Une <strong>Radiographie Thoracique (RXT)</strong> pour identifier des anomalies pulmonaires.</li></ul>"},{"i":"3ad93e834801","n":203,"o":"203-5","u":"Diagnostic positif","t":"Connaître les éléments d’orientation diagnostique face à une dyspnée chronique","q":"Quelle est la définition de la dyspnée chronique en médecine?","a":"<p>La dyspnée chronique est définie par une <strong>gêne respiratoire persistante égale ou supérieure à 8 semaines</strong>.</p>"},{"i":"439f1a0aa7c2","n":203,"o":"203-5","u":"Diagnostic positif","t":"Connaître les éléments d’orientation diagnostique face à une dyspnée chronique","q":"Comment doit-on quantifier l'impact de la dyspnée chronique chez un patient?","a":"<p>La quantification de l'impact de la dyspnée chronique s'effectue à l'aide de plusieurs outils :</p><ul><li>Les échelles de gravité : <strong>échelle mMRC</strong> (dyspnée respiratoire) et <strong>classification NYHA</strong> (dyspnée cardiaque).</li><li>Les outils d'évaluation de la qualité de vie ou des symptômes associés : <strong>CAT</strong> (BPCO), <strong>HAD/HADS</strong> (anxiété-dépression).</li><li>Autres échelles : Score DIRECT, EVA, Borg.</li></ul>"},{"i":"dd0fdcd3093a","n":203,"o":"203-5","u":"Diagnostic positif","t":"Connaître les éléments d’orientation diagnostique face à une dyspnée chronique","q":"Quels examens complémentaires sont indiqués en cas de suspicion d'orientation cardiaque pour une dyspnée chronique?","a":"<p>En cas de suspicion d'orientation cardiaque devant une dyspnée chronique, les examens complémentaires à réaliser sont :</p><ul><li>Un <strong>avis cardiologique spécialisé</strong>.</li><li>Une <strong>Échocardiographie TransThoracique (ETT) avec Doppler</strong>.</li><li>Le dosage du <strong>BNP ou du NT-proBNP</strong> : des valeurs de BNP &lt; <strong>35 pg/mL</strong> ou NT-proBNP &lt; <strong>125 pg/mL</strong> permettent d'exclure une insuffisance cardiaque chronique.</li></ul>"},{"i":"1bd0b7f2b78c","n":203,"o":"203-6","u":"Etiologies","t":"Connaître les signes d’orientation étiologique","q":"Quelles informations sémiologiques spécifiques (bruits respiratoires) permettent d'orienter vers une obstruction des voies aériennes supérieures et quelles en sont les étiologies potentielles en urgence ?","a":"<ul><li>Un <strong>stridor inspiratoire aigu</strong> oriente vers un <strong>obstacle laryngé sus- ou glottique</strong>. C'est une urgence évoquant une <strong>épiglottite</strong>, un <strong>œdème laryngé</strong> ou un <strong>corps étranger</strong>.</li><li>Un <strong>cornage inspiratoire rauque</strong> oriente vers un <strong>obstacle sous-glottique</strong>, typique de la <strong>laryngite sous-glottique de l'enfant</strong>.</li></ul>"},{"i":"20d2e461b602","n":203,"o":"203-6","u":"Etiologies","t":"Connaître les signes d’orientation étiologique","q":"Quelle est la signification d'une orthopnée concernant la dyspnée, et quelles étiologies spécifiques sont évoquées ?","a":"<p>L'orthopnée est une dyspnée qui survient en position allongée et est soulagée en position assise ou debout.</p><ul><li>Elle oriente vers une <strong>insuffisance cardiaque globale (ICG)</strong>.</li><li>Elle peut aussi évoquer un <strong>syndrome cave supérieur</strong>, une <strong>dysfonction diaphragmatique</strong> ou une <strong>obésité morbide</strong>.</li></ul>"},{"i":"530d62f66abc","n":203,"o":"203-6","u":"Etiologies","t":"Connaître les signes d’orientation étiologique","q":"Quelles sont les principales étiologies à considérer devant un wheezing expiratoire, ou des sibilants à l'auscultation pulmonaire ?","a":"<ul><li>Un <strong>wheezing expiratoire</strong> évoque principalement l'<strong>asthme</strong>, la <strong>BPCO</strong>, ou un <strong>pseudo-asthme cardiaque</strong> (manifestation d'une insuffisance cardiaque).</li><li>Des <strong>sibilants</strong> à l'auscultation sont également des signes d'<strong>asthme</strong>, de <strong>BPCO</strong>, ou d'<strong>insuffisance cardiaque globale (ICG)</strong> responsable d'un pseudo-asthme.</li></ul>"},{"i":"61b6f7b01fd9","n":203,"o":"203-6","u":"Etiologies","t":"Connaître les signes d’orientation étiologique","q":"Pourquoi une auscultation pulmonaire normale peut-elle être un piège majeur dans l'évaluation d'une dyspnée, et quelles étiologies spécifiques ne doivent pas être écartées ?","a":"<p>Une <strong>auscultation pulmonaire normale</strong> (dite <em>sine materia</em>) ne permet pas d'éliminer des diagnostics graves.</p><ul><li>Elle peut masquer une <strong>embolie pulmonaire (EP)</strong>, une <strong>tamponnade cardiaque</strong>, une <strong>maladie neuromusculaire</strong>, une <strong>obésité</strong>, une <strong>scoliose</strong> ou un <strong>syndrome d'hyperventilation</strong>.</li><li>Chez un patient <strong>tabagique</strong>, <strong>immobilisé</strong> ou ayant des <strong>antécédents néoplasiques</strong>, l'<strong>embolie pulmonaire</strong> doit être envisagée jusqu'à preuve du contraire.</li></ul>"},{"i":"8cbffc513e7c","n":203,"o":"203-6","u":"Etiologies","t":"Connaître les signes d’orientation étiologique","q":"Quelles sont les étiologies à rechercher en présence d'une platypnée ?","a":"<p>Une platypnée est une dyspnée qui apparaît ou s'aggrave en position debout et s'améliore en décubitus.</p><ul><li>Elle est très évocatrice d'un <strong>shunt anatomique</strong>, tel qu'un <strong>foramen ovale perméable (FOP)</strong>, une <strong>fistule artério-veineuse pulmonaire</strong> ou un <strong>syndrome hépato-pulmonaire</strong>.</li></ul>"},{"i":"af311b28c992","n":203,"o":"203-6","u":"Etiologies","t":"Connaître les signes d’orientation étiologique","q":"Quels sont les diagnostics à envisager face à des crépitants ou une abolition du murmure vésiculaire à l'auscultation pulmonaire ?","a":"<ul><li>Des <strong>crépitants</strong> orientent vers une <strong>pneumopathie interstitielle diffuse (PID)</strong>, une <strong>insuffisance cardiaque globale (ICG)</strong> ou une <strong>pneumonie aiguë communautaire (PAC)</strong>.</li><li>Une <strong>abolition du murmure vésiculaire</strong> associée à un <strong>tympanisme</strong> évoque un <strong>pneumothorax (PNO)</strong>.</li><li>Une <strong>abolition du murmure vésiculaire</strong> associée à une <strong>matité</strong> évoque une <strong>pleurésie</strong>.</li></ul>"},{"i":"b4a2bbc8b4ad","n":203,"o":"203-6","u":"Etiologies","t":"Connaître les signes d’orientation étiologique","q":"Quelles sont les étiologies principales des dyspnées de Kussmaul et de Cheyne-Stokes ?","a":"<ul><li>Une <strong>dyspnée de Kussmaul</strong> (ample, profonde, à 4 temps) est évocatrice d'une <strong>acidose métabolique</strong> (comme l'<strong>acidocétose</strong>, l'<strong>insuffisance rénale aiguë (IRA)</strong> sévère ou un <strong>sepsis</strong>).</li><li>Une <strong>dyspnée de Cheyne-Stokes</strong> (cycles d'apnées et d'hyperpnées progressives) est fréquente en cas d'<strong>insuffisance cardiaque grave (IC grave)</strong> ou de <strong>syndrome d'apnées du sommeil central (SAS central)</strong>.</li></ul>"},{"i":"0fe96b812f82","n":203,"o":"203-7","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","q":"Quels sont les seuils du BNP ou NT-proBNP permettant d'écarter une insuffisance cardiaque en cas de dyspnée chronique ?","a":"<p>Devant une dyspnée chronique, une insuffisance cardiaque chronique est exclue si :</p><ul><li>Le <strong>BNP est inférieur à 35 pg/mL</strong></li><li>Le <strong>NT-proBNP est inférieur à 125 pg/mL</strong></li></ul><p>Il est crucial de noter que ces seuils diffèrent radicalement de ceux de la dyspnée aiguë.</p>"},{"i":"0fea2f3f9b83","n":203,"o":"203-7","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","q":"Devant une dyspnée aiguë, à partir de quel score de Wells considère-t-on l'EP comme probable, et quelle est l'attitude diagnostique associée ?","a":"<p>Devant une dyspnée aiguë, selon la version dichotomique du score de Wells, l'embolie pulmonaire est considérée comme <strong>probable si le score est supérieur à 4</strong>.</p><p>Dans ce cas, en raison d'une probabilité pré-test élevée, il convient de réaliser une <strong>angio-TDM thoracique d'emblée</strong>, sans doser les D-dimères (qui risqueraient des faux négatifs ou une perte de temps).</p>"},{"i":"79ea8a149f55","n":203,"o":"203-7","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","q":"Dans quels cas les D-dimères sont-ils indiqués en première intention devant une dyspnée aiguë, et quelle est leur interprétation ?","a":"<p>Les D-dimères sont indiqués en première intention devant une dyspnée aiguë si une suspicion d'embolie pulmonaire (EP) est évoquée et que la <strong>probabilité clinique est faible ou intermédiaire</strong> (évaluée par un score de Wells ou de Genève simplifié).</p><ul><li>Si les D-dimères sont <strong>inférieurs à 500 pg/mL</strong> (ou seuil ajusté à l'âge > 50 ans : âge x 10 pg/mL), l'EP est <strong>exclue</strong>.</li><li>Si les D-dimères sont élevés, une angio-TDM sera réalisée.</li></ul>"},{"i":"a5aa9761a401","n":203,"o":"203-7","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","q":"Quels sont les seuils du BNP ou NT-proBNP permettant d'écarter une insuffisance cardiaque en cas de dyspnée aiguë ?","a":"<p>Devant une dyspnée aiguë, une insuffisance cardiaque est peu probable si :</p><ul><li>Le <strong>BNP est inférieur à 100 pg/mL</strong></li><li>Le <strong>NT-proBNP est inférieur à 300 pg/mL</strong></li></ul><p>Des taux élevés suggèrent une IC, avec des seuils ajustés à l'âge (e.g., >450 pg/mL si <55 ans ; >900 pg/mL si 55-75 ans ; >1800 pg/mL si >75 ans).</p>"},{"i":"ba8faafb42e0","n":203,"o":"203-7","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","q":"Quels sont les examens complémentaires de première intention à réaliser devant une dyspnée chronique ?","a":"<p>Devant une dyspnée chronique (≥ 8 semaines), les examens complémentaires de première intention systématiques sont :</p><ul><li>La <strong>numération formule sanguine (NFS)</strong></li><li>L'<strong>électrocardiogramme (ECG)</strong></li><li>La <strong>radiographie thoracique (RXT)</strong></li></ul>"},{"i":"eef43d32e48c","n":203,"o":"203-7","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention en fonction du caractère aigu ou chronique","q":"Quels sont les examens complémentaires de première intention à réaliser devant une dyspnée aiguë ?","a":"<p>Devant une dyspnée aiguë (≤ 8 semaines), les examens complémentaires de première intention systématiques sont :</p><ul><li>Les <strong>gaz du sang (GDS)</strong></li><li>L'<strong>électrocardiogramme (ECG)</strong></li><li>La <strong>radiographie thoracique (RXT)</strong></li></ul>"},{"i":"0e9ce82f699d","n":203,"o":"203-8","u":"Examens complémentaires","t":"Connaître les examens complémentaires de seconde intention en fonction du caractère aigu ou chronique","q":"Quels sont les examens complémentaires de seconde intention à considérer pour une dyspnée chronique d'orientation cardiaque ?","a":"<p>Pour une dyspnée chronique d'orientation cardiaque, les examens de seconde intention sont :<ul><li>Un <strong>avis cardiologique</strong>.</li><li>Une <strong>échographie transthoracique (ETT) systématique</strong>.</li><li>Un dosage des <strong>BNP/NT-proBNP de confirmation</strong>, si nécessaire.</li></ul></p>"},{"i":"23b92b25f905","n":203,"o":"203-8","u":"Examens complémentaires","t":"Connaître les examens complémentaires de seconde intention en fonction du caractère aigu ou chronique","q":"Quel examen complémentaire de seconde intention est pertinent face à une suspicion d'insuffisance cardiaque (IC) en cas de dyspnée aiguë, après les examens de première intention ?","a":"<p>Face à une suspicion d'insuffisance cardiaque, l'examen de seconde intention est l'<strong>échographie transthoracique (ETT) avec doppler</strong>.</p>"},{"i":"340cac057d96","n":203,"o":"203-8","u":"Examens complémentaires","t":"Connaître les examens complémentaires de seconde intention en fonction du caractère aigu ou chronique","q":"Quels examens complémentaires de seconde intention sont indiqués pour un approfondissement fonctionnel devant une dyspnée aiguë lorsque les explorations initiales ne sont pas suffisantes ?","a":"<p>Pour un approfondissement fonctionnel en cas de dyspnée aiguë, les examens de seconde intention peuvent inclure :<ul><li>Les <strong>explorations fonctionnelles respiratoires (EFR)</strong>.</li><li>Le <strong>cathétérisme cardiaque</strong>.</li><li>L'<strong>épreuve d'effort métabolique (EFX)</strong>.</li></ul></p>"},{"i":"384839d5627b","n":203,"o":"203-8","u":"Examens complémentaires","t":"Connaître les examens complémentaires de seconde intention en fonction du caractère aigu ou chronique","q":"Quels examens complémentaires de seconde intention peuvent être envisagés en cas de suspicion d'embolie pulmonaire (EP) face à une dyspnée aiguë après les examens de première intention ?","a":"<p>En cas de suspicion d'embolie pulmonaire, les examens de seconde intention comprennent :<ul><li>L'<strong>échodoppler veineux des membres inférieurs</strong>.</li><li>L'<strong>angio-TDM thoracique</strong>.</li><li>La <strong>scintigraphie V/P</strong> (ventilation/perfusion).</li></ul></p>"},{"i":"ba169a477a7e","n":203,"o":"203-8","u":"Examens complémentaires","t":"Connaître les examens complémentaires de seconde intention en fonction du caractère aigu ou chronique","q":"Quels sont les examens complémentaires respiratoires de seconde intention pour une dyspnée chronique ?","a":"<p>Les examens complémentaires respiratoires de seconde intention pour une dyspnée chronique comprennent :<ul><li>Les <strong>EFR de repos</strong> : spirométrie lente, pléthysmographie et <strong>DLCO</strong> (diffusion alvéolo-capillaire).</li><li>Les <strong>gaz du sang (GDS) de repos</strong> pour rechercher une hypoxémie ou une hypoventilation alvéolaire chronique.</li><li>Les <strong>EFR d'exercice</strong> : épreuve d'effort inspiratoire (EFXi) sur cycloergomètre ou tests simples comme le <strong>test de marche de 6 minutes</strong> ou le lever de chaise de 3 minutes (avec une cible de baisse de SpO2 ≥ 3%).</li><li>Le <strong>TDM thoracique</strong> : non injecté si suspicion de BPCO ou de pathologie interstitielle diffuse (PID) ; injecté si cause vasculaire (embolie pulmonaire chronique, HTP, shunt D-G).</li></ul></p>"}]};